INSERT INTO `audit_logs` VALUES ('au_647832a829aa','tn_04250683f1b3','usr_1aadc023e041','Zepto','tenant_admin','Updated voice settings','voice_bot','bot_59a84478f155','Zepto MDND Support','{\"botId\": \"bot_59a84478f155\", \"speed\": 1.1, \"energy\": 15, \"empathy\": 0, \"pauseMs\": 250, \"voiceId\": \"vp-sv-kavya\", \"llmModel\": \"gpt-4o-mini\", \"sttModel\": \"saaras:v3\", \"ttsModel\": \"bulbul:v3\", \"ttsVoice\": \"\", \"goalPolicy\": {\"summaryFields\": [{\"name\": \"call_customer\", \"type\": \"yes_no\", \"label\": \"Called the customer\", \"source\": \"m_called_customer\", \"description\": \"Did the delivery partner call the customer before attempting the delivery?\"}, {\"name\": \"reach_customer_location\", \"type\": \"yes_no\", \"label\": \"Reached customer location\", \"source\": \"m_reached_location\", \"description\": \"Did the delivery partner reach the customer\'s location for the delivery?\"}, {\"name\": \"hand_over_product\", \"type\": \"yes_no\", \"label\": \"Product handed over\", \"source\": \"m_handover_recipient\", \"values\": {\"*\": \"Yes\", \"not handed over\": \"No\"}, \"description\": \"Was the product actually handed over to anyone (the customer, a guard, a relative, left at the doorstep, or someone else)?\"}, {\"name\": \"hand_over_to\", \"type\": \"choice\", \"label\": \"Handed over to\", \"source\": \"m_handover_recipient\", \"values\": {\"father\": \"father\", \"mother\": \"mother\", \"brother\": \"brother\", \"left at door\": \"doorstep\", \"someone else\": \"someone_else\", \"not handed over\": \"\", \"guard / security\": \"security_guard\", \"relative (other)\": \"relative\", \"customer (direct)\": \"customer\", \"place (kept at a spot)\": \"\"}, \"options\": [\"customer\", \"security_guard\", \"mother\", \"father\", \"brother\", \"relative\", \"doorstep\", \"someone_else\"], \"requires\": {\"handover_type\": [\"person\", \"place\"]}, \"description\": \"Who received the product.\"}, {\"name\": \"handover_type\", \"type\": \"choice\