--
-- Table structure for table `bot_languages`
--

DROP TABLE IF EXISTS `bot_languages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bot_languages` (
  `bot_id` varchar(40) NOT NULL,
  `language_code` varchar(15) NOT NULL,
  PRIMARY KEY (`bot_id`,`language_code`),
  KEY `language_code` (`language_code`),
  CONSTRAINT `bot_languages_ibfk_1` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`),
