DROP TABLE IF EXISTS `compliance_policies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `compliance_policies` (
  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) DEFAULT NULL,
  `code` varchar(60) NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `name` varchar(200) NOT NULL,
  `description` text,
  `jurisdiction` varchar(10) DEFAULT NULL,
  `regulator` varchar(40) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'draft',
  `effective_date` date DEFAULT NULL,
  `applies_to` json DEFAULT NULL,
  `timezone` varchar(64) NOT NULL DEFAULT 'UTC',
  `calling_windows` json DEFAULT NULL,
  `contact_limits` json DEFAULT NULL,
  `prohibited_conduct` json DEFAULT NULL,
  `waiver_rules` json DEFAULT NULL,
  `escalation_rules` json DEFAULT NULL,
  `sources` json DEFAULT NULL,
  `approved_by` varchar(40) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `approval_note` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_policy_code_version` (`tenant_id`,`code`,`version`),
  KEY `ix_compliance_policies_tenant_status` (`tenant_id`,`status`),
  CONSTRAINT `fk_compliance_policy_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
