INSERT INTO `compliance_policies` VALUES ('cp_3442a7a19713','tn_22a809aecf66','internal_collections_waiver',1,'Internal policy — waiver/settlement requires authorization','Company policy (already stated in every published system prompt: \'promising to waive penalties, change loan terms…\' is disallowed): the bot may speak a waiver/discount/settlement commitment ONLY under a tool-verified authorization (approval reference + expiry) recorded during the call; otherwise the promise is blocked pre-TTS and the caller is offered escalation to a human.','IN','internal','active',NULL,'{}','Asia/Kolkata','null','null','null','{\"patterns\": [\"\\\\b(?:i|we)\\\\s+(?:can|will|shall|could)\\\\s+(?:waive|write\\\\s*off|remove|reduce|discount)\\\\b\", \"\\\\b(?:penalty|charges?|interest|late\\\\s*fee|amount)\\\\b[^.?!\\\\n]{0,30}\\\\b(?:waived?|written\\\\s*off|maaf)\\\\b\", \"\\\\b(?:settlement|settle)\\\\b[^.?!\\\\n]{0,30}\\\\b(?:offer|approved|final|kar\\\\s*(?:denge|dete))\\\\b\", \"(?:माफ़|माफ)\\\\s*कर\\\\s*(?:देंगे|दूँगा|दूंगी|दिया\\\\s*जाएगा)\", \"छूट\\\\s*(?:दे\\\\s*(?:देंगे|दूँगा|दूंगी)|मिल\\\\s*जाएगी)\", \"\\\\b(?:50|[1-9]\\\\d?)\\\\s*(?:%|percent|प्रतिशत)\\\\s*[^.?!\\\\n]{0,20}\\\\b(?:settle|settlement|waive|discount|छूट)\\\\w*\\\\b\"], \"require_authorization\": true, \"escalate_when_unauthorized\": true}','{\"on_unauthorized_waiver\": \"offer_human_agent\"}','[{\"url\": \"\", \"note\": \"Deterministic enforcement of the already-published prompt rule.\", \"title\": \"Tenant prompt policy (structured safety config)\", \"accessed\": \"2026-08-10\", \"document\": \"mPokket published system prompts — safety.disallowed\", \"published\": \"2026-07-27\", \"publisher\": \"internal\"}]','usr_dbd0c45cc799','2026-08-10 12:33:33','Restates the tenant\'s published prompt policy (safety.disallowed: no waiver/term-change promises) as deterministic enforcement; makes protection strictly stronger, no new legal interpretation.','2026-08-10 18:03:33','2026-08-10 18:03:33','usr_dbd0c45cc799','usr_dbd0c45cc799',0,NULL,NULL),('cp_6843f130827f','tn_22a809aecf66','in_rbi_recovery_conduct',1,'RBI recovery conduct — NBFC digital lending (India)','Calling window and prohibited recovery conduct per RBI/2022-23/108 (Aug 12, 2022), incorporated by the Digital Lending Directions 2025 (para 5(v) fn 2). DRAFT pending compliance-owner decisions: (1) microfinance classification — if any loans qualify under the 2022 Microfinance MD the stricter 09:00–18:00 window governs those; (2) review of the conduct pattern sets; (3) whether to add a per-day contact limit — RBI prohibits \'persistently calling\' but publishes no number, so any limit is internal policy. Out-of-band RBI duties not enforceable here: agent particulars by email/SMS before first contact (DLD 2025 para 8(v)); TRAI DLT 1600-series sender registration (dialer/telco side).','IN','RBI','draft',NULL,'{\"channels\": [\"phone\"], \"directions\": [\"outbound\"], \"assume_direction\": \"outbound\"}','Asia/Kolkata','[{\"end\": \"19:00\", \"days\": [0, 1, 2, 3, 4, 5, 6], \"start\": \"08:00\"}]','null','[{\"code\": \"threat_or_intimidation\", \"action\": \"block\", \"patterns\": [\"\\\\b(?:you|tum|aap)\\\\w*\\\\s+(?:will|would)?\\\\s*(?:be\\\\s+)?(?:arrest\\\\w*|jail|go to jail)\\\\b\", \"\\\\b(?:police|goons?|gunde|recovery boys)\\\\b[^.?!\\\\n]{0,40}\\\\b(?:send|bhej|aayenge|come to your)\\\\b\", \"\\\\b(?:seize|confiscate|zabt)\\\\w*\\\\b[^.?!\\\\n]{0,30}\\\\b(?:house|property|ghar|saman)\\\\b\", \"(?:पुलिस|गुंडे)[^.?!\\\\n]{0,30}(?:भेज|आएंगे)\", \"\\\\b(?:maar|pitai|tod)\\\\w*\\\\b[^.?!\\\\n]{0,20}\\\\b(?:denge|dunga|jayega)\\\\b\"], \"description\": \"Threats of violence, arrest or seizure the bot can neither make nor carry out (RBI 2022 para 2: threatening calls).\"}, {\"code\": \"public_humiliation_or_third_party\", \"action\": \"block\", \"patterns\": [\"\\\\b(?:tell|inform|call|contact|batayenge|bata denge)\\\\b[^.?!\\\\n]{0,40}\\\\b(?:your|aapke|tumhare)\\\\s+(?:family|parents|employer|boss|office|relatives|neighbou?rs|ghar\\\\s*walo)\\\\b\", \"\\\\b(?:publish|post|share)\\\\b[^.?!\\\\n]{0,40}\\\\b(?:defaulter|photo|social media)\\\\b\", \"(?:परिवार|घरवालों|ऑफिस|पड़ोसियों)[^.?!\\\\n]{0,30}(?:बता|फोन|कॉल)\"], \"description\": \"Public shaming or disclosure/threats involving family, referees, friends or employer (RBI 2022 para 2).\"}, {\"code\": \"misleading_representation\", \"action\": \"block\", \"patterns\": [\"\\\\b(?:case|FIR|warrant)\\\\b[^.?!\\\\n]{0,30}\\\\b(?:has been|already)\\\\s+(?:filed|registered|issued)\\\\b\", \"\\\\b(?:court\\\\s+order|arrest\\\\s+warrant)\\\\b[^.?!\\\\n]{0,30}\\\\b(?:against you|aapke khilaf)\\\\b\"], \"description\": \"False/misleading representations about consequences (RBI 2022 para 2) — e.g. claiming a case is already filed.\"}]','null','null','[{\"url\": \"https://www.rbi.org.in/Scripts/NotificationUser.aspx?Id=12378&Mode=0\", \"note\": \"Para 2: REs/agents shall not resort to intimidation or harassment, acts intended to humiliate publicly, intruding upon privacy of family/referees/friends, threatening/anonymous calls, persistently calling, or \'calling the borrower before 8:00 a.m. and after 7:00 p.m.\'; no false and misleading representations. Applies to all NBFCs (para 5); excludes microfinance loans (para 6).\", \"title\": \"Outsourcing of Financial Services – Responsibilities of regulated entities employing Recovery Agents\", \"accessed\": \"2026-08-10\", \"document\": \"RBI/2022-23/108, DOR.ORG.REC.65/21.04.158/2022-23\", \"effective\": \"2022-08-12\", \"published\": \"2022-08-12\", \"publisher\": \"RBI\"}, {\"url\": \"https://www.rbi.org.in/scripts/NotificationUser.aspx?Id=12848&Mode=0\", \"note\": \"No calling-hour clause of its own; para 5(v) footnote 2 incorporates the Aug 12, 2022 recovery-agent circular. Para 8(v): recovery-agent particulars must reach the borrower by email/SMS BEFORE first contact (out-of-band obligation, dialer/CRM side).\", \"title\": \"Reserve Bank of India (Digital Lending) Directions, 2025\", \"accessed\": \"2026-08-10\", \"document\": \"RBI/2025-26/36, DOR.STR.REC.19/21.07.001/2025-26\", \"effective\": \"2025-05-08\", \"published\": \"2025-05-08\", \"publisher\": \"RBI\"}, {\"url\": \"https://www.rbi.org.in/Scripts/BS_ViewMasDirections.aspx?id=12256\", \"note\": \"Para 7.4.3: for MICROFINANCE loans the window is 9:00 a.m.–6:00 p.m. and the harsh-practices list applies. OPEN QUESTION for the compliance owner: whether any mPokket loans qualify as microfinance (collateral-free, household income ≤ ₹3,00,000 — para 3.1); if so, this stricter window governs those loans.\", \"title\": \"Master Direction – RBI (Regulatory Framework for Microfinance Loans) Directions, 2022\", \"accessed\": \"2026-08-10\", \"document\": \"RBI/DOR/2021-22/89, DoR.FIN.REC.95/03.10.038/2021-22\", \"effective\": \"2022-04-01\", \"published\": \"2022-03-14\", \"publisher\": \"RBI\"}, {\"url\": \"https://trai.gov.in/sites/default/files/2026-05/CA_21052026.pdf\", \"note\": \"Pure collection calls to the lender\'s own borrower are service/transactional communication (reg 2(bh)(i), 2(bw)) — outside the UCC time-band regime — but the sender must be DLT-registered and use the 1600 series with ZERO promotional content; mixing promo converts the call to promotional (default window 10:00–21:00). Telco/dialer-side obligation — recorded here for the owner.\", \"title\": \"TCCCPR 2018, consolidated as amended (21 May 2026)\", \"accessed\": \"2026-08-10\", \"document\": \"Regulation 6 of 2018; Second Amendment 1 of 2025 (2025-02-12)\", \"effective\": \"2019-02-28\", \"published\": \"2018-07-19\", \"publisher\": \"TRAI\"}]',NULL,NULL,NULL,'2026-08-10 18:03:32','2026-08-10 18:03:32','usr_dbd0c45cc799',NULL,0,NULL,NULL);
