  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `conversation_id` varchar(40) NOT NULL,
  `session_id` varchar(64) NOT NULL,
  `bot_id` varchar(40) NOT NULL,
  `channel` varchar(20) NOT NULL DEFAULT 'voice',
  `runtime_context_record_id` varchar(40) DEFAULT NULL,
  `customer_context_id` varchar(40) DEFAULT NULL,
  `phone_tail` varchar(15) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'queued',
  `attempts` int NOT NULL DEFAULT '0',
  `max_attempts` int NOT NULL DEFAULT '3',
  `error` text,
  `started_processing_at` datetime DEFAULT NULL,
  `generated_at` datetime DEFAULT NULL,
  `final_state` json DEFAULT NULL,
  `call_outcome` varchar(60) DEFAULT NULL,
  `summary` text,
  `memory` json DEFAULT NULL,
  `next_action` varchar(60) DEFAULT NULL,
  `next_best_action` json DEFAULT NULL,
  `follow_up_required` tinyint(1) NOT NULL DEFAULT '0',
  `follow_up_at` datetime DEFAULT NULL,
  `confidence` decimal(4,3) DEFAULT NULL,
  `language` varchar(15) DEFAULT NULL,
  `dominant_language` varchar(15) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_conversation_memory` (`conversation_id`),
  KEY `ix_conversation_memories_tenant_id` (`tenant_id`),
  KEY `ix_conversation_memories_bot_id` (`bot_id`),
  KEY `ix_conv_memory_record` (`tenant_id`,`bot_id`,`runtime_context_record_id`,`created_at`),
  KEY `ix_conv_memory_cctx` (`tenant_id`,`bot_id`,`customer_context_id`,`created_at`),
  KEY `ix_conv_memory_phone` (`tenant_id`,`bot_id`,`phone_tail`,`created_at`),
  KEY `ix_conv_memory_status` (`status`,`created_at`),
  CONSTRAINT `conversation_memories_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`),
  CONSTRAINT `conversation_memories_ibfk_2` FOREIGN KEY (`conversation_id`) REFERENCES `conversation_sessions` (`id`),
  CONSTRAINT `conversation_memories_ibfk_3` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
