DROP TABLE IF EXISTS `conversation_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `conversation_sessions` (
  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `bot_id` varchar(40) NOT NULL,
  `channel` varchar(20) NOT NULL,
  `caller_masked` varchar(50) DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `duration_sec` int NOT NULL,
  `sentiment` varchar(10) NOT NULL,
  `intents` json DEFAULT NULL,
  `contained` tinyint(1) NOT NULL,
  `escalation_reason` varchar(300) DEFAULT NULL,
  `csat` int DEFAULT NULL,
  `cost_usd` decimal(12,6) NOT NULL,
  `language` varchar(15) DEFAULT NULL,
  `qa_score` int DEFAULT NULL,
  `flagged` tinyint(1) NOT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `is_deleted` tinyint(1) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  `session_id` varchar(64) DEFAULT NULL,
  `disposition` varchar(40) DEFAULT NULL,
  `prompt_id` varchar(40) DEFAULT NULL,
  `prompt_version` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_conversations_bot_started` (`bot_id`,`started_at`),
  KEY `ix_conversations_tenant_started` (`tenant_id`,`started_at`),
  KEY `ix_conversations_session` (`session_id`),
  CONSTRAINT `conversation_sessions_ibfk_1` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`),
  CONSTRAINT `conversation_sessions_ibfk_2` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
