INSERT INTO `guardrail_profiles` VALUES ('gp_162eb6cbf1a0','standard','Standard','Baseline conversational safety: PII redaction plus abuse de-escalation on top of the mandatory platform rules.','active',1,'2026-08-10 15:36:08','2026-08-10 15:36:08',NULL,NULL,0,NULL,NULL),('gp_36403cb61d4e','ecommerce_support','E-commerce Support','Customer-support voice bots for e-commerce/D2C brands: abuse de-escalation plus a hard block on the bot ever requesting card numbers, CVV, OTPs or PINs, on top of the mandatory platform guardrails.','active',1,'2026-08-27 20:47:19','2026-08-27 20:47:19','usr_dbd0c45cc799',NULL,0,NULL,NULL),('gp_60ac7e16e678','education_counselling','Education Counselling','Outbound admissions/counselling voice bots for education institutes: abuse de-escalation plus a hard block on the bot ever requesting card numbers, CVV, OTPs or PINs (seminar bookings are free; fee payment never happens on a call), on top of the mandatory platform guardrails.','active',1,'2026-08-31 15:50:36','2026-08-31 15:50:36','usr_dbd0c45cc799',NULL,0,NULL,NULL),('gp_6a139d0dd017','logistics_partner_support','Logistics Partner Support','Inbound support voice bots for logistics / quick-commerce delivery partners raising payout deduction concerns: abuse de-escalation plus a hard block on the bot ever requesting card numbers, CVV, OTPs, PINs or UPI credentials (the bot only records complaint details; payouts are settled by the payouts team, never on a call), on top of the mandatory platform guardrails.','active',1,'2026-08-31 17:18:55','2026-08-31 17:18:55','usr_dbd0c45cc799',NULL,0,NULL,NULL),('gp_a71c05b5a7b5','finance','Finance','Standard plus payment & advice restrictions — balances may be referenced, card numbers never collected.','active',1,'2026-08-10 15:36:08','2026-08-10 15:36:08',NULL,NULL,0,NULL,NULL),('gp_c24345d8d4ac','travel_hospitality','Travel and Hospitality','Standard plus booking & payment restrictions — no guaranteed bookings, refunds or free upgrades by voice, and card numbers are never collected.','active',1,'2026-08-14 10:42:15','2026-08-14 10:42:15',NULL,NULL,0,NULL,NULL),('gp_cbb8dc3216fa','development','Development / Internal','Internal test bots: no real telephony calls, no state-changing tools. Mandatory platform rules still apply.','active',1,'2026-08-10 17:47:12','2026-08-10 17:47:12',NULL,NULL,0,NULL,NULL),('gp_d9c1675434c4','healthcare','Healthcare','Standard plus a medical-advice boundary — no diagnosis or dosage advice by voice.','active',1,'2026-08-10 15:36:08','2026-08-10 15:36:08',NULL,NULL,0,NULL,NULL);
