INSERT INTO `guardrails` VALUES ('gr_3399290ffb62','Secret & credential leakage prevention','Privacy','Redacts API keys, tokens and passwords from model output, transcripts and process logs.','redact',1,0,'2026-08-10 15:36:08','2026-08-10 17:27:44',NULL,NULL,0,NULL,NULL,'secret_leakage_prevention',1),('gr_3a1ebfe203b7','Booking & fare commitment restriction','Compliance','Blocks guaranteed bookings, refunds, fee waivers or free upgrades the bot cannot verify; tool-confirmed facts may still be stated.','block',1,0,'2026-08-14 10:42:15','2026-08-14 10:42:15',NULL,NULL,0,NULL,NULL,'booking_commitment_restriction',0),('gr_429d4eb2bf6c','Account-changing tools disabled','Development','Blocks state-changing (non-mock) tool/API executions for this bot.','block',1,0,'2026-08-10 17:47:12','2026-08-10 17:47:12',NULL,NULL,0,NULL,NULL,'state_changing_tool_block',0),('gr_484690e9a25b','Medical advice boundary','Safety','Blocks diagnosis or dosage advice; routes to licensed staff.','block',1,3,'2026-07-15 14:34:09','2026-09-22 13:58:55',NULL,'usr_dbd0c45cc799',0,NULL,NULL,'medical_advice_boundary',0),('gr_640dfd0c4bd7','Profanity / abuse de-escalation','Safety','Switches to calm register and offers human handover on repeated abuse.','flag',1,0,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL,'profanity_deescalation',0),('gr_895fccf38da8','Payment collection restriction','Compliance','Bots may reference balances but never collect card numbers by voice.','block',1,7,'2026-07-15 14:34:09','2026-09-21 19:16:31',NULL,NULL,0,NULL,NULL,'payment_collection_restriction',0),('gr_a9b2c693b720','PII redaction in transcripts','Privacy','Redacts SSN, card numbers and DOB from stored transcripts and logs.','redact',1,0,'2026-07-15 14:34:09','2026-08-10 17:27:44',NULL,'usr-demo-super',0,NULL,NULL,'pii_redaction',1),('gr_ded6c5c07029','Competitor mention flag','Brand','Flags conversations where competitors are discussed for QA review.','flag',0,0,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL,'competitor_mention_flag',0),('gr_e127924b6ffe','Prompt-injection protection','Security','Flags injection attempts in caller speech and retrieved knowledge; scope rules force the bot back on-goal.','flag',1,0,'2026-08-10 15:36:08','2026-08-10 15:36:08',NULL,NULL,0,NULL,NULL,'prompt_injection_protection',1),('gr_e4b81b8de309','Unsafe tool-call blocking','Security','Blocks tool/API calls outside the bot\'s allow-list and any tool call after a blocking guardrail fired in the same turn.','block',1,0,'2026-08-10 15:36:08','2026-08-10 17:27:44',NULL,NULL,0,NULL,NULL,'unsafe_tool_call_block',1),('gr_ef92163d2714','Telephony calls disabled','Development','Blocks telephony calls for this bot — browser/web test sessions only.','block',1,0,'2026-08-10 17:47:12','2026-08-10 17:47:12',NULL,NULL,0,NULL,NULL,'outbound_call_block',0);
