-- Table structure for table `knowledge_sources`
--

DROP TABLE IF EXISTS `knowledge_sources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `knowledge_sources` (
  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) DEFAULT NULL,
  `bot_id` varchar(40) DEFAULT NULL,
  `scope` varchar(10) NOT NULL,
  `type` varchar(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `detail` varchar(500) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `chunks` int NOT NULL,
  `size_kb` int NOT NULL,
  `last_sync_at` datetime DEFAULT NULL,
  `quality` int NOT NULL,
  `usage_30d` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_knowledge_sources_bot_id` (`bot_id`),
  KEY `ix_knowledge_sources_tenant_id` (`tenant_id`),
  KEY `ix_knowledge_tenant_scope` (`tenant_id`,`scope`),
  CONSTRAINT `knowledge_sources_ibfk_1` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`),
  CONSTRAINT `knowledge_sources_ibfk_2` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

