anary 5%','{\"status\": \"draft\"}','active',4,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_8790882a0341','prompt_version','Safety preamble v8 → v9','Published · approved by platform admin','{\"status\": \"published\"}','active',6,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_9439d5fc4074','action_block','Book appointment','Write a booking into the scheduling system.','{\"icon\": \"calendar\"}','active',19,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_955fc3dde318','journey_template','Order tracking','Order id → status → proactive delay handling.','{\"nodes\": 6}','active',13,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_a408d4b9e66d','action_block','Send email','Send a templated email.','{\"icon\": \"mail\"}','active',17,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_a76fcb63afa3','prompt_library','Payment reminder call','Outbound dunning script with promise-to-pay capture.','{\"category\": \"Billing\"}','active',1,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_bb283905a6b6','prompt_library','Order status lookup','Order-tracking flow grounded in the commerce API.','{\"category\": \"Retail\"}','active',3,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_bbb762d9abb2','action_block','Warm transfer','Transfer the call with context to an agent queue.','{\"icon\": \"phone\"}','active',20,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_c670cb07ecb0','knowledge_template','Healthcare FAQ pack','Starter FAQ structure for clinics: hours, insurance, prep.','{\"items\": 60}','active',7,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_ca4eea0614bb','action_block','Knowledge answer','Answer from retrieval with citations.','{\"icon\": \"book\"}','active',22,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_cad51acf7cf6','journey_template','Password / account reset','Verify → reset link → confirm.','{\"nodes\": 5}','active',14,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_d86fe55d92cc','action_block','Escalation ticket','Open a ticket in the connected helpdesk.','{\"icon\": \"alert\"}','active',23,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_dc77286bb250','knowledge_template','Banking security pack','Verification scripts and fraud escalation knowledge.','{\"items\": 44}','active',9,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_dc7c48e5d030','journey_template','Appointment booking','Slot lookup → verify → confirm → SMS recap.','{\"nodes\": 10}','active',10,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL),('pt_ff26568052ec','action_block','Create CRM record','Create or update a CRM contact/case.','{\"icon\": \"database\"}','active',18,'2026-07-15 14:34:09','2026-07-15 14:34:09',NULL,NULL,0,NULL,NULL);
