--
-- Table structure for table `prompt_versions`
--

DROP TABLE IF EXISTS `prompt_versions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prompt_versions` (
  `id` varchar(40) NOT NULL,
  `prompt_id` varchar(40) NOT NULL,
  `version` int NOT NULL,
  `edited_by` varchar(150) DEFAULT NULL,
  `edited_by_user_id` varchar(40) DEFAULT NULL,
  `edited_at` datetime DEFAULT NULL,
  `note` varchar(500) DEFAULT NULL,
  `variants` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `structured_config` json DEFAULT NULL,
  `compiled_prompt` mediumtext,
  `model_compatibility` json DEFAULT NULL,
  `prompt_mode` varchar(20) NOT NULL DEFAULT 'structured',
  `full_prompt` mediumtext,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_prompt_version` (`prompt_id`,`version`),
  KEY `ix_prompt_versions_prompt_id` (`prompt_id`),
  CONSTRAINT `prompt_versions_ibfk_1` FOREIGN KEY (`prompt_id`) REFERENCES `prompts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

