DROP TABLE IF EXISTS `prompts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prompts` (
  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `bot_id` varchar(40) NOT NULL,
  `type` varchar(20) NOT NULL,
  `name` varchar(200) NOT NULL,
  `variables` json DEFAULT NULL,
  `state` varchar(30) NOT NULL,
  `active_version` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  `description` varchar(500) DEFAULT NULL,
  `published_version` int DEFAULT NULL,
  `approved_by` varchar(150) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_prompts_bot` (`bot_id`),
  KEY `ix_prompts_tenant_id` (`tenant_id`),
  CONSTRAINT `prompts_ibfk_1` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`),
  CONSTRAINT `prompts_ibfk_2` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

