  `deleted_by` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_pronunciation_dictionaries_tenant_id` (`tenant_id`),
  KEY `ix_pronunciation_dictionaries_provider_dict_id` (`provider_dict_id`),
  CONSTRAINT `pronunciation_dictionaries_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`)
