-5 family rejects. Activate only after the provider is updated.'),('pm_ff8f7b2bc085','elevenlabs','tts','eleven_flash_v2_5','Eleven Flash v2.5','[\"en\", \"hi\", \"ta\", \"ja\", \"zh\", \"de\", \"fr\", \"ko\", \"pt\", \"it\", \"es\", \"id\", \"nl\", \"tr\", \"fil\", \"pl\", \"sv\", \"bg\", \"ro\", \"ar\", \"cs\", \"el\", \"fi\", \"hr\", \"ms\", \"sk\", \"da\", \"uk\", \"ru\", \"hu\", \"no\", \"vi\"]','[\"pcm\", \"ulaw\", \"alaw\"]','[8000, 16000, 22050, 24000]',1,'{\"speed\": {\"max\": 1.2, \"min\": 0.7, \"help\": \"Playback speed multiplier.\", \"step\": 0.05, \"type\": \"number\", \"label\": \"Speed\", \"default\": 1.0}, \"style\": {\"max\": 1.0, \"min\": 0.0, \"help\": \"Style exaggeration. 0 is fastest and most stable.\", \"step\": 0.05, \"type\": \"number\", \"label\": \"Style\", \"default\": 0.0}, \"auto_mode\": {\"help\": \"Generate immediately per sentence instead of server-side buffering. Recommended when sending complete sentences (this platform does).\", \"type\": \"boolean\", \"label\": \"Auto mode\", \"default\": true}, \"stability\": {\"max\": 1.0, \"min\": 0.0, \"help\": \"Lower values give more expressive, varied delivery; higher values are steadier.\", \"step\": 0.05, \"type\": \"number\", \"label\": \"Stability\", \"default\": 0.0}, \"sync_alignment\": {\"help\": \"Deliver character timing data in sync with audio chunks.\", \"type\": \"boolean\", \"label\": \"Sync alignment\", \"default\": false, \"advanced\": true}, \"similarity_boost\": {\"max\": 1.0, \"min\": 0.0, \"help\": \"How closely synthesis adheres to the original voice timbre.\", \"step\": 0.05, \"type\": \"number\", \"label\": \"Similarity boost\", \"default\": 1.0}, \"use_speaker_boost\": {\"help\": \"Boosts similarity to the original speaker at a small latency cost.\", \"type\": \"boolean\", \"label\": \"Speaker boost\", \"default\": true}, \"inactivity_timeout\": {\"max\": 180, \"min\": 20, \"help\": \"Server-side idle timeout for the streaming connection.\", \"type\": \"integer\", \"label\": \"Inactivity timeout (s)\", \"default\": 60, \"advanced\": true}, \"chunk_length_schedule\": {\"max\": 500, \"min\": 50, \"help\": \"Character thresholds that trigger generation when auto mode is off.\", \"type\": \"int_list\", \"label\": \"Chunk schedule\", \"default\": [120, 160, 250, 290], \"advanced\": true, \"max_items\": 8}, \"apply_text_normalization\": {\"help\": \"Normalize numbers/abbreviations before synthesis.\", \"type\": \"enum\", \"label\": \"Text normalization\", \"values\": [\"auto\", \"on\", \"off\"], \"default\": \"auto\", \"advanced\": true}}',1,'active',0,'2026-07-21 18:25:14','2026-07-21 18:25:14',NULL,NULL,0,NULL,NULL,'Ultra-low-latency model (~75 ms) for realtime conversation over the streaming WebSocket. 32 languages, 40,000-character limit. Recommended for live calls.');
