DROP TABLE IF EXISTS `provider_pricing`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `provider_pricing` (
  `id` varchar(40) NOT NULL,
  `provider_code` varchar(50) NOT NULL,
  `capability` varchar(20) NOT NULL,
  `model_code` varchar(80) NOT NULL,
  `component` varchar(30) NOT NULL,
  `unit` varchar(20) NOT NULL,
  `unit_price` decimal(18,10) NOT NULL,
  `currency_code` varchar(3) NOT NULL DEFAULT 'USD',
  `effective_from` datetime NOT NULL DEFAULT (now()),
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  `selling_price` decimal(18,10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pricing_key_effective` (`provider_code`,`capability`,`model_code`,`component`,`effective_from`),
  KEY `fk_pricing_currency` (`currency_code`),
  KEY `ix_provider_pricing_status` (`status`),
  KEY `ix_pricing_lookup` (`provider_code`,`capability`,`model_code`,`status`),
  CONSTRAINT `fk_pricing_currency` FOREIGN KEY (`currency_code`) REFERENCES `currencies` (`code`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

