DROP TABLE IF EXISTS `tenants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tenants` (
  `id` varchar(40) NOT NULL,
  `name` varchar(200) NOT NULL,
  `domain` varchar(255) NOT NULL,
  `industry` varchar(100) DEFAULT NULL,
  `region` varchar(50) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `health` varchar(20) NOT NULL,
  `admin_email` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  `code` varchar(50) DEFAULT NULL,
  `ai_profile_code` varchar(50) DEFAULT NULL,
  `website` varchar(300) DEFAULT NULL,
  `contact_name` varchar(150) DEFAULT NULL,
  `contact_email` varchar(255) DEFAULT NULL,
  `contact_phone` varchar(30) DEFAULT NULL,
  `address` varchar(500) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `call_summary_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `use_previous_call_summary` tinyint(1) NOT NULL DEFAULT '0',
  `guardrail_profile_id` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `domain` (`domain`),
  UNIQUE KEY `uq_tenants_code` (`code`),
  KEY `ix_tenants_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
