--
-- Table structure for table `usage_events`
--

DROP TABLE IF EXISTS `usage_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usage_events` (
  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `bot_id` varchar(40) DEFAULT NULL,
  `session_id` varchar(40) DEFAULT NULL,
  `capability` varchar(20) NOT NULL,
  `provider_code` varchar(50) NOT NULL,
  `model_code` varchar(80) DEFAULT NULL,
  `voice_code` varchar(80) DEFAULT NULL,
  `request_id` varchar(120) DEFAULT NULL,
  `occurred_at` datetime NOT NULL DEFAULT (now()),
  `requests` int NOT NULL DEFAULT '1',
  `input_tokens` int NOT NULL DEFAULT '0',
  `output_tokens` int NOT NULL DEFAULT '0',
  `cached_tokens` int NOT NULL DEFAULT '0',
  `reasoning_tokens` int NOT NULL DEFAULT '0',
  `total_tokens` int NOT NULL DEFAULT '0',
  `characters` int NOT NULL DEFAULT '0',
  `audio_seconds` decimal(12,3) NOT NULL DEFAULT '0.000',
  `usage_source` varchar(20) NOT NULL DEFAULT 'provider',
  `usage_metadata` json DEFAULT NULL,
  `pricing_status` varchar(20) NOT NULL DEFAULT 'priced',
  `pricing_snapshot` json DEFAULT NULL,
  `cost_usd` decimal(14,6) NOT NULL DEFAULT '0.000000',
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `charge_usd` decimal(14,6) NOT NULL DEFAULT '0.000000',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_usage_event_request` (`request_id`),
  KEY `bot_id` (`bot_id`),
  KEY `ix_usage_events_tenant_time` (`tenant_id`,`occurred_at`),
  KEY `ix_usage_events_capability_time` (`capability`,`occurred_at`),
  KEY `ix_usage_events_provider` (`provider_code`,`model_code`),
  CONSTRAINT `usage_events_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`),
  CONSTRAINT `usage_events_ibfk_2` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

