--
-- Table structure for table `usage_records`
--

DROP TABLE IF EXISTS `usage_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usage_records` (
  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `bot_id` varchar(40) DEFAULT NULL,
  `date` date NOT NULL,
  `calls` int NOT NULL,
  `contained_calls` int NOT NULL,
  `escalations` int NOT NULL,
  `minutes` decimal(12,2) NOT NULL,
  `csat_avg` float DEFAULT NULL,
  `cost_llm` decimal(10,4) NOT NULL,
  `cost_tts` decimal(10,4) NOT NULL,
  `cost_stt` decimal(10,4) NOT NULL,
  `cost_telephony` decimal(10,4) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `cost_embedding` decimal(10,4) NOT NULL DEFAULT '0.0000',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_usage_tenant_bot_date` (`tenant_id`,`bot_id`,`date`),
  KEY `bot_id` (`bot_id`),
  KEY `ix_usage_date` (`date`),
  KEY `ix_usage_tenant_date` (`tenant_id`,`date`),
  CONSTRAINT `usage_records_ibfk_1` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`),
  CONSTRAINT `usage_records_ibfk_2` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

