--
-- Table structure for table `voice_bot_settings`
--

DROP TABLE IF EXISTS `voice_bot_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `voice_bot_settings` (
  `id` varchar(40) NOT NULL,
  `bot_id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `voice_id` varchar(40) DEFAULT NULL,
  `speed` float NOT NULL,
  `pause_ms` int NOT NULL,
  `empathy` int NOT NULL,
  `energy` int NOT NULL,
  `language_voice_map` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `stt_provider` varchar(40) DEFAULT NULL,
  `stt_model` varchar(80) DEFAULT NULL,
  `tts_provider` varchar(40) DEFAULT NULL,
  `tts_model` varchar(80) DEFAULT NULL,
  `tts_voice` varchar(80) DEFAULT NULL,
  `llm_provider` varchar(40) DEFAULT NULL,
  `llm_model` varchar(80) DEFAULT NULL,
  `stt_language` varchar(15) DEFAULT NULL,
  `stt_settings` json DEFAULT NULL,
  `tts_settings` json DEFAULT NULL,
  `llm_settings` json DEFAULT NULL,
  `fallback_provider` varchar(40) DEFAULT NULL,
  `fallback_model` varchar(80) DEFAULT NULL,
  `fallback_voice` varchar(80) DEFAULT NULL,
  `audio_settings` json DEFAULT NULL,
  `goal_policy` json DEFAULT NULL,
  `human_speech` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bot_id` (`bot_id`),
  KEY `voice_id` (`voice_id`),
  KEY `ix_voice_bot_settings_tenant_id` (`tenant_id`),
  CONSTRAINT `voice_bot_settings_ibfk_1` FOREIGN KEY (`bot_id`) REFERENCES `voice_bots` (`id`),
  CONSTRAINT `voice_bot_settings_ibfk_2` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`),
  CONSTRAINT `voice_bot_settings_ibfk_3` FOREIGN KEY (`voice_id`) REFERENCES `voice_profiles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

