DROP TABLE IF EXISTS `voice_bots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `voice_bots` (
  `id` varchar(40) NOT NULL,
  `name` varchar(200) NOT NULL,
  `use_case` varchar(200) DEFAULT NULL,
  `description` text,
  `status` varchar(20) NOT NULL,
  `version` varchar(20) NOT NULL,
  `live_version` varchar(20) DEFAULT NULL,
  `owner_user_id` varchar(40) DEFAULT NULL,
  `health` varchar(20) NOT NULL,
  `containment` float NOT NULL,
  `avg_cost_per_call` decimal(8,4) NOT NULL,
  `csat` float NOT NULL,
  `voice_id` varchar(40) DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `guardrail_profile_id` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `owner_user_id` (`owner_user_id`),
  KEY `voice_id` (`voice_id`),
  KEY `ix_voice_bots_tenant_id` (`tenant_id`),
  KEY `ix_voice_bots_tenant_status` (`tenant_id`,`status`),
  CONSTRAINT `voice_bots_ibfk_1` FOREIGN KEY (`owner_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `voice_bots_ibfk_2` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`),
  CONSTRAINT `voice_bots_ibfk_3` FOREIGN KEY (`voice_id`) REFERENCES `voice_profiles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

