INSERT INTO `voice_bots` VALUES ('bot_0340b2424b2c','WF Bot a0538d22',NULL,NULL,'draft','v0.1.0',NULL,NULL,'neutral',0,0.0000,0,NULL,NULL,'2026-08-25 15:27:02','2026-08-25 15:27:02',NULL,NULL,0,NULL,NULL,'tn_bcd9fa05b459',NULL),('bot_059e49443c76','Frankfinn Seminar Booking','Outbound seminar-seat booking (admissions)','Outbound Hinglish admissions bot for Frankfinn Institute of Air Hostess Training. Calls students who showed interest in aviation, hospitality, travel and customer-service careers, checks eligibility (12th pass mandate, final-year probe for third-year graduation students), pitches the free 45-minute career counselling seminar at the Ahmedabad C G Road centre, books a seat, and confirms the appointment SMS, Aadhaar-card entry requirement and the 1800 258 7332 helpline. Built from Frankfinn\'s approved Quality Call Flow document and a reference call recording.','published','v0.1.0','v0.1.0','usr_f46b98f946ec','neutral',0,0.0000,0,'vp-sv-shubh','2026-08-31 10:41:21','2026-08-31 15:52:27','2026-09-01 12:28:58','usr_f46b98f946ec','usr_f46b98f946ec',0,NULL,NULL,'tn_6553beac240d',NULL),('bot_0ded44cd4fb6','Clone Source 16708fae4c (copy 2)','Billing support','The template bot','draft','v0.1.0',NULL,'usr_c9eb4f926313','neutral',0,0.0000,0,NULL,NULL,'2026-08-25 20:49:08','2026-08-25 20:49:08','usr_c9eb4f926313',NULL,0,NULL,NULL,'tn_ae9d817e8fed',NULL),('bot_10627738b8be','ZZ Workflow UI Test (scratch)','collections','temporary UI test bot','archived','v0.1.0',NULL,'usr_48f09517dcda','neutral',0,0.0000,0,NULL,NULL,'2026-08-27 18:18:45','2026-08-27 18:19:06','usr_48f09517dcda',NULL,1,'2026-08-27 12:49:06','usr_48f09517dcda','tn_22a809aecf66',NULL),('bot_125312abf3fe','Fresh Bot 16708fae4c','FAQ & information','','draft','v0.1.0',NULL,'usr_c9eb4f926313','neutral',0,0.0000,0,NULL,NULL,'2026-08-25 20:49:09','2026-08-25 20:49:09','usr_c9eb4f926313',NULL,0,NULL,NULL,'tn_ae9d817e8fed',NULL),('bot_1afce3d3a37b','Sarvam E2E Check','','temporary sarvam tts e2e','archived'