DROP TABLE IF EXISTS `voice_clone_audio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `voice_clone_audio` (
  `id` varchar(40) NOT NULL,
  `tenant_id` varchar(40) NOT NULL,
  `voice_id` varchar(40) NOT NULL,
  `original_filename` varchar(255) NOT NULL,
  `storage_path` varchar(500) NOT NULL,
  `mime_type` varchar(100) NOT NULL,
  `size_bytes` int NOT NULL DEFAULT '0',
  `duration_sec` float DEFAULT NULL,
  `source_type` varchar(20) NOT NULL DEFAULT 'file_upload',
  `provider` varchar(100) DEFAULT NULL,
  `provider_voice_id` varchar(100) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'stored',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` varchar(40) DEFAULT NULL,
  `updated_by` varchar(40) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_voice_clone_audio_tenant_id` (`tenant_id`),
  KEY `ix_voice_clone_audio_voice_id` (`voice_id`),
  CONSTRAINT `fk_voice_clone_audio_tenant_id` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`),
  CONSTRAINT `fk_voice_clone_audio_voice_id` FOREIGN KEY (`voice_id`) REFERENCES `voice_profiles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

