INSERT INTO `workflows` VALUES ('wf_017f18b83e77','tn_ae9d817e8fed','bot_0ded44cd4fb6','Billing journey',2,'approved','[{\"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"id\": \"n2\", \"kind\": \"api\", \"label\": \"Fetch invoice\", \"config\": {\"connectionId\": \"api_54399042c4f5\"}}, {\"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-08-25 20:49:08','2026-08-25 20:49:08','usr_c9eb4f926313',NULL,0,NULL,NULL),('wf_0cd3c1c7c0c8','tn_22a809aecf66','bot_80487d7ce2e9','Payment commitment',8,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Customer agreed to pay\"}, {\"x\": 40, \"y\": 150, \"id\": \"n_type\", \"kind\": \"intent\", \"label\": \"Full or partial\", \"config\": {\"prompt\": \"क्या आप पूरा payment करेंगे, या अभी partial payment करेंगे?\"}}, {\"x\": 300, \"y\": 260, \"id\": \"n_partial_amount\", \"kind\": \"ask\", \"label\": \"Partial amount\", \"config\": {\"entity\": {\"dataType\": \"text\", \"regexPattern\": \"((?:\\\\d[\\\\d,]*(?:\\\\.\\\\d+)?(?!\\\\d))|(?:एक|दो|तीन|चार|पाँच|पांच|छह|सात|आठ|नौ|दस|ग्यारह|बारह|पंद्रह|बीस|पच्चीस|तीस|चालीस|पचास)\\\\s*(?:सौ|हज़ार|हजार)?)(?!\\\\s*(?:तारीख|tarikh|tareekh|को\\\\b))\"}, \"question\": \"आप आज कितना payment कर सकते हैं?\", \"variable\": \"partial_amount\"}}, {\"x\": 300, \"y\": 370, \"id\": \"n_balance_date\", \"kind\": \"ask\", \"label\": \"Balance date\", \"config\": {\"entity\": {\"dataType\": \"text\", \"regexPattern\": \"^\\\\s*(.*?(?:\\\\d{1,2}\\\\s*[/-]\\\\s*\\\\d{1,2}|\\\\d{4}-\\\\d{2}-\\\\d{2}|tarikh|tareekh|तारीख|जनवरी|फ़रवरी|फरवरी|मार्च|अप्रैल|मई|जून|जुलाई|अगस्त|सितंबर|सितम्बर|अक्टूबर|नवंबर|नवम्बर|दिसंबर|दिसम्बर|(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*|आज|कल|परसों|aaj|kal|parso|सोमवार|मंगलवार|बुधवार|गुरुवार|शुक्रवार|शनिवार|रविवार|इतवार|monday|tuesday|wednesday|thursday|friday|saturday|sunday).*?)\\\\s*$\"}, \"question\": \"बाकी amount आप किस तारीख तक complete कर पाएंगे?\", \"variable\": \"balance_date\"}}, {\"x\": 40, \"y\": 480, \"id\": \"n_method\", \"kind\": \"ask\", \"label\": \"Mode of payment\", \"config\": {\"entity\": {\"dataType\": \"text\", \"synonyms\": {\"UPI\": [\"upi\", \"यूपीआई\", \"यू पी आई\", \"भीम\", \"bhim\", \"paytm\", \"पेटीएम\", \"gpay\", \"google pay\", \"phonepe\", \"फोन पे\", \"qr\"], \"Debit Card\": [\"debit\", \"card\", \"डेबिट\", \"कार्ड\", \"atm\", \"एटीएम\"]}, \"allowedValues\": [\"UPI\", \"Debit Card\"]}, \"question\": \"Payment आप किस माध्यम से करेंगे — U P I या डेबिट कार्ड?\", \"variable\": \"payment_method\"}}, {\"x\": 40, \"y\": 590, \"id\": \"n_verify\", \"kind\": \"api\", \"label\": \"payment_status\", \"config\": {\"connection\": \"payment_status\"}}, {\"x\": 300, \"y\": 700, \"id\": \"n_paid\", \"kind\": \"end\", \"label\": \"Payment verified\", \"config\": {\"text\": \"आपका payment successfully receive हो गया है। समय देने के लिए धन्यवाद, आपका दिन शुभ हो।\"}}, {\"x\": 40, \"y\": 700, \"id\": \"n_committed\", \"kind\": \"end\", \"label\": \"Commitment recorded\", \"config\": {\"text\": \"ठीक है, आपका commitment note कर लिया गया है। धन्यवाद, आपका दिन शुभ हो।\"}}, {\"x\": 560, \"y\": 480, \"id\": \"n_agent\", \"kind\": \"handover\", \"label\": \"Agent\", \"config\": {\"queue\": \"collections\"}}]','[{\"id\": \"e1\", \"to\": \"n_type\", \"from\": \"n_start\"}, {\"id\": \"e2\", \"to\": \"n_method\", \"from\": \"n_type\", \"label\": \"full/poora/pura/पूरा/complete\"}, {\"id\": \"e3\", \"to\": \"n_partial_amount\", \"from\": \"n_type\", \"label\": \"partial/aadha/थोड़ा/किस्त/part\"}, {\"id\": \"e4\", \"to\": \"n_balance_date\", \"from\": \"n_partial_amount\"}, {\"id\": \"e5\", \"to\": \"n_agent\", \"from\": \"n_partial_amount\", \"label\": \"fallback\"}, {\"id\": \"e6\", \"to\": \"n_method\", \"from\": \"n_balance_date\"}, {\"id\": \"e7\", \"to\": \"n_agent\", \"from\": \"n_balance_date\", \"label\": \"fallback\"}, {\"id\": \"e8\", \"to\": \"n_verify\", \"from\": \"n_method\"}, {\"id\": \"e9\", \"to\": \"n_agent\", \"from\": \"n_method\", \"label\": \"fallback\"}, {\"id\": \"e10\", \"to\": \"n_committed\", \"from\": \"n_verify\", \"label\": \"failure\"}, {\"id\": \"e11\", \"to\": \"n_paid\", \"from\": \"n_verify\", \"label\": \"success\"}]','[]','2026-08-04 13:20:42','2026-08-05 12:57:27','usr_c22173241fc4',NULL,0,NULL,NULL),('wf_0cd968c4357b','tn_22a809aecf66','bot_827e05799518','Scratch journey renamed',6,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}, {\"x\": 180, \"y\": 270, \"id\": \"n_8818hq\", \"kind\": \"message\", \"label\": \"Welcome\", \"config\": {\"text\": \"Hello! This is a test.\", \"responseMode\": \"exact\"}}, {\"x\": 280, \"y\": 170, \"id\": \"n_3o8ia6\", \"kind\": \"end\", \"label\": \"End\", \"config\": {}}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}, {\"id\": \"e_6iia5f\", \"to\": \"n_8818hq\", \"from\": \"n1\"}, {\"id\": \"e_djc1ps\", \"to\": \"n_3o8ia6\", \"from\": \"n_8818hq\"}]','[]','2026-08-27 19:13:44','2026-08-27 19:13:54','usr_48f09517dcda','usr_48f09517dcda',0,NULL,NULL),('wf_0ed2a40c7c57','tn_22a809aecf66','bot_2911266a8d39','collections journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-08-27 19:12:17','2026-08-27 19:12:17','usr_48f09517dcda',NULL,0,NULL,NULL),('wf_149881af322a','tn-001','bot_8af840b4bc0c','Sarvam E2E Check journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-23 19:32:52','2026-07-23 19:32:52','usr-demo-priya',NULL,0,NULL,NULL),('wf_15942ec9ffe3','tn_6a2b6c99de33','bot_8f410775e3f6','FAQ & information journey',3,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Inbound call starts\", \"config\": {}}, {\"x\": 40, \"y\": 150, \"id\": \"n_greeting\", \"kind\": \"message\", \"label\": \"Greeting\", \"config\": {\"text\": \"Hello, welcome to Lenovo Customer Support. I am your virtual service assistant. How may I help you today?\", \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 280, \"id\": \"n_intent\", \"kind\": \"intent\", \"label\": \"Identify customer intent\", \"config\": {\"allowedValues\": [\"service_centre_details\", \"warranty_general_faq\", \"unsupported_or_unclear\"]}}, {\"x\": 40, \"y\": 420, \"id\": \"n_sc_location\", \"kind\": \"ask\", \"label\": \"Capture PIN code or locality\", \"config\": {\"rule\": \"Accept EITHER pincode OR city/locality; accept both if given together. If already stated in the triggering utterance, extract and skip this node entirely.\", \"parse_to\": [\"service_centre_locator.pincode\", \"service_centre_locator.city\", \"service_centre_locator.locality\"], \"question\": \"Sure. Please tell me your PIN code or city so I can find the nearest authorised service centre.\", \"variable\": \"service_centre_locator.location_input\", \"condition\": \"pincode AND city AND locality are all unavailable\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 550, \"id\": \"n_sc_area_clarify\", \"kind\": \"ask\", \"label\": \"Area clarification (only if insufficient)\", \"config\": {\"rule\": \"Ask ONLY if the given city/PIN is genuinely insufficient for the lookup source. Ask once only.\", \"question\": \"Which area or locality should I check?\", \"variable\": \"service_centre_locator.locality\", \"condition\": \"city present AND locality/pincode still insufficient for lookup\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 680, \"id\": \"n_sc_search\", \"kind\": \"api\", \"label\": \"Search service centre directory\", \"config\": {\"rule\": \"Query against service_centre_master using whichever of pincode/city/locality is available. Never invent results. This node has NO standalone spoken output of its own: any optional filler line (e.g. \'Sure, let me check that.\') must be emitted fused into the SAME response as the immediate_next_node\'s message (n_sc_one_result / n_sc_multi_result), never as a separate turn that waits for the customer. Do not trigger silence_recovery on this node or in the gap before the next node fires.\", \"inputs\": {\"city\": \"service_centre_locator.city\", \"pincode\": \"service_centre_locator.pincode\", \"locality\": \"service_centre_locator.locality\"}, \"condition\": \"pincode OR (city AND locality) available\", \"connection\": \"service_centre_lookup\", \"on_failure\": \"n_sc_fail\", \"on_success\": \"immediate_next_node\", \"silence_recovery_enabled\": false, \"expects_customer_response\": false, \"backend_pending_is_not_customer_silence\": true}}, {\"x\": -260, \"y\": 820, \"id\": \"n_sc_one_result\", \"kind\": \"message\", \"label\": \"Announce single centre + offer contact\", \"config\": {\"rule\": \"Speak ONLY fields returned in service_centre_locator.results[0]. Offer the contact number as a question here — do not speak the number yet. Times: speak opening_time/closing_time exactly as their AM/PM value (e.g. \'9:30 AM to 7:00 PM\') even in Hindi/Hinglish output — never convert to \'baje\' phrasing, never say \'baje\' twice.\", \"format\": \"The nearest authorised Lenovo service centre is {results[0].centre_name}, located at {results[0].address}. It is open {results[0].working_days} from {results[0].opening_time} to {results[0].closing_time}. Would you also like the contact number?\", \"tts_safe\": true, \"dynamic_source\": \"service_centre_locator.results\", \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 820, \"id\": \"n_sc_multi_result\", \"kind\": \"message\", \"label\": \"Announce multiple centres + offer contact\", \"config\": {\"rule\": \"Limit to the 2-3 nearest returned results only. Speak ONLY fields returned by the API. Times: speak opening_time/closing_time exactly as their AM/PM value — never convert to \'baje\' phrasing, never say \'baje\' twice.\", \"format\": \"I found a few authorised Lenovo service centres near you. The nearest is {results[0].centre_name} at {results[0].address}. Another option is {results[1].centre_name} at {results[1].address}. Would you like the contact details for either centre?\", \"tts_safe\": true, \"dynamic_source\": \"service_centre_locator.results\", \"expects_customer_response\": true}}, {\"x\": 340, \"y\": 820, \"id\": \"n_sc_fail\", \"kind\": \"handover\", \"label\": \"No centre found / lookup failure\", \"config\": {\"rule\": \"Never invent or suggest an unverified third-party centre.\", \"queue\": \"lenovo_customer_support\", \"condition\": \"no matching result or lookup failure\"}}, {\"x\": -100, \"y\": 950, \"id\": \"n_sc_contact\", \"kind\": \"message\", \"label\": \"Share contact number (separate turn)\", \"config\": {\"rule\": \"Only reached after customer confirms yes. Speak ONLY the phone_number field of the selected/only centre. Do not repeat address/hours here.\", \"format\": \"You can contact the centre on {selected_centre.phone_number}.\", \"tts_safe\": true, \"condition\": \"contact_number_offered=true AND customer confirmed yes\", \"dynamic_source\": \"service_centre_locator.selected_centre_index\"}}, {\"x\": -100, \"y\": 1070, \"id\": \"n_sc_hours_faq\", \"kind\": \"message\", \"label\": \"Working hours / open-today answer (re-entrant)\", \"config\": {\"rule\": \"Reachable at any point after a centre result exists, whenever the customer asks about timings or if it is open today. Only assert \'open now/today\' if a live open/closed status is available; otherwise state listed hours only. Times: speak opening_time/closing_time exactly as their AM/PM value — never convert to \'baje\' phrasing, never say \'baje\' twice.\", \"format\": \"The listed working hours are {selected_centre.working_days}, {selected_centre.opening_time} to {selected_centre.closing_time}.\", \"tts_safe\": true, \"dynamic_source\": \"service_centre_locator.selected_centre_index\", \"expects_customer_response\": false}}, {\"x\": -100, \"y\": 1190, \"id\": \"n_sc_end\", \"kind\": \"end\", \"label\": \"Service centre journey completed\", \"config\": {\"text\": \"Thank you for contacting Lenovo Customer Support. Have a good day.\"}}, {\"x\": 800, \"y\": 280, \"id\": \"n_unsupported\", \"kind\": \"handover\", \"label\": \"Unsupported request\", \"config\": {\"queue\": \"lenovo_customer_support\"}}, {\"x\": 500, \"y\": 1350, \"id\": \"n_wty_ask\", \"kind\": \"ask\", \"label\": \"Capture warranty question\", \"config\": {\"rule\": \"If the triggering utterance already contains a specific warranty question, extract it and skip this node entirely.\", \"question\": \"Sure. What would you like to know about your warranty?\", \"variable\": \"warranty_general_faq.raw_question_input\", \"condition\": \"no specific warranty question captured yet\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 500, \"y\": 1470, \"id\": \"n_wty_match\", \"kind\": \"intent\", \"label\": \"Match question against knowledge base\", \"config\": {\"rule\": \"Match by meaning/keywords, not exact wording, against lenovo_warranty_faq_knowledge_base. Internal, instant operation — never end a turn on a filler alone; fuse any filler with the Step 3 answer in the same response, and never trigger silence-recovery around the match.\", \"variable\": \"warranty_general_faq.matched_topic_code\", \"allowedValues\": [\"WTY_WHAT_IS\", \"WTY_START_DATE\", \"WTY_DURATION\", \"WTY_PHYSICAL_DAMAGE\", \"WTY_LIQUID_DAMAGE\", \"WTY_FREE_REPAIR\", \"WTY_DOCUMENTS_REQUIRED\", \"WTY_LOST_INVOICE\", \"WTY_FULL_REPLACEMENT\", \"WTY_SPARE_PARTS\", \"WTY_AUTHORISED_CENTRE_ONLY\", \"WTY_REPAIR_EXTENDS_WARRANTY\", \"case_specific_confirmation_request\", \"unmatched_or_out_of_scope\"]}}, {\"x\": 380, \"y\": 1600, \"id\": \"n_wty_answer\", \"kind\": \"message\", \"label\": \"Speak matched knowledge-base answer\", \"config\": {\"rule\": \"Speak the stored approved_answer for warranty_general_faq.matched_topic_code word for word. Do not paraphrase, shorten, or add unapproved detail.\", \"format\": \"{matched_entry.approved_answer}\", \"tts_safe\": true, \"dynamic_source\": \"lenovo_warranty_faq_knowledge_base\", \"expects_customer_response\": false}}, {\"x\": 380, \"y\": 1720, \"id\": \"n_wty_followup\", \"kind\": \"ask\", \"label\": \"Offer another warranty question\", \"config\": {\"rule\": \"If the reply is itself a new warranty question (barge-in), treat it as a new capture and route straight to n_wty_match instead of re-asking.\", \"question\": \"Is there anything else I can help you with?\", \"variable\": \"warranty_general_faq.followup_response\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 650, \"y\": 1600, \"id\": \"n_wty_case_specific\", \"kind\": \"message\", \"label\": \"Case-specific guardrail response\", \"config\": {\"rule\": \"Never infer eligibility from symptoms. Never soften this into an implied yes/no. Do not confirm or deny coverage. If the customer insists further after this line, add: \'I am unable to approve a warranty claim without the required verification.\' before moving to the redirect offer.\", \"text\": \"Warranty eligibility depends on the product, reported issue and applicable warranty terms. The authorised service team may need to inspect the product before confirming coverage.\", \"expects_customer_response\": false}}, {\"x\": 650, \"y\": 1720, \"id\": \"n_wty_case_redirect\", \"kind\": \"ask\", \"label\": \"Offer service-centre redirect\", \"config\": {\"question\": \"Would you like me to find the nearest authorised service centre for this?\", \"variable\": \"warranty_general_faq.redirect_to_service_centre_response\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 380, \"y\": 1470, \"id\": \"n_wty_unmatched\", \"kind\": \"ask\", \"label\": \"Unmatched / out-of-scope question\", \"config\": {\"rule\": \"Track warranty_general_faq.unmatched_attempts. Reset to 0 on any successful match.\", \"question\": \"I\'m sorry, I don\'t have information on that specific question. Could you rephrase it, or ask something else about your warranty?\", \"variable\": \"warranty_general_faq.raw_question_input\", \"condition\": \"no matching knowledge-base entry AND not a case-specific push\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 380, \"y\": 1350, \"id\": \"n_wty_escalate\", \"kind\": \"handover\", \"label\": \"Warranty FAQ fallback\", \"config\": {\"queue\": \"lenovo_customer_support\", \"condition\": \"second consecutive unmatched question, or customer asks for a human\"}}, {\"x\": 500, \"y\": 1840, \"id\": \"n_closing_check\", \"kind\": \"ask\", \"label\": \"Shared closing check (both flows)\", \"config\": {\"rule\": \"Reached whenever either flow reaches a natural completion point. If the customer\'s affirmative reply already states a new request, route straight into that flow (skip n_reopen). If affirmative but unspecified, go to n_reopen first. Never default into a specific flow just because it\'s the only other configured one.\", \"question\": \"Is there anything else I can help you with?\", \"variable\": \"closing_check.response\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 650, \"y\": 1960, \"id\": \"n_reopen\", \"kind\": \"message\", \"label\": \"Re-open for a fresh intent\", \"config\": {\"text\": \"Sure, how can I help you?\", \"expects_customer_response\": true}}]','[{\"id\": \"e1\", \"to\": \"n_greeting\", \"from\": \"n_start\"}, {\"id\": \"e2\", \"to\": \"n_intent\", \"from\": \"n_greeting\"}, {\"id\": \"e3\", \"to\": \"n_sc_location\", \"from\": \"n_intent\", \"label\": \"service_centre_details\"}, {\"id\": \"e4\", \"to\": \"n_unsupported\", \"from\": \"n_intent\", \"label\": \"unsupported_or_unclear\"}, {\"id\": \"e5\", \"to\": \"n_sc_search\", \"from\": \"n_sc_location\", \"label\": \"pincode OR (city+locality) sufficient\"}, {\"id\": \"e6\", \"to\": \"n_sc_area_clarify\", \"from\": \"n_sc_location\", \"label\": \"city present but locality/pincode insufficient\"}, {\"id\": \"e7\", \"to\": \"n_sc_search\", \"from\": \"n_sc_area_clarify\", \"label\": \"locality captured\"}, {\"id\": \"e8\", \"to\": \"n_sc_one_result\", \"from\": \"n_sc_search\", \"label\": \"exactly 1 result; immediate transition\"}, {\"id\": \"e9\", \"to\": \"n_sc_multi_result\", \"from\": \"n_sc_search\", \"label\": \"2+ results; immediate transition\"}, {\"id\": \"e10\", \"to\": \"n_sc_fail\", \"from\": \"n_sc_search\", \"label\": \"0 results or lookup failure\"}, {\"id\": \"e11\", \"to\": \"n_sc_contact\", \"from\": \"n_sc_one_result\", \"label\": \"customer confirms yes\"}, {\"id\": \"e12\", \"to\": \"n_closing_check\", \"from\": \"n_sc_one_result\", \"label\": \"customer declines contact number\"}, {\"id\": \"e13\", \"to\": \"n_sc_contact\", \"from\": \"n_sc_multi_result\", \"label\": \"customer picks a centre and confirms yes\"}, {\"id\": \"e14\", \"to\": \"n_closing_check\", \"from\": \"n_sc_multi_result\", \"label\": \"customer declines contact number\"}, {\"id\": \"e15\", \"to\": \"n_sc_hours_faq\", \"from\": \"n_sc_one_result\", \"label\": \"customer asks about timings / open today\"}, {\"id\": \"e16\", \"to\": \"n_sc_hours_faq\", \"from\": \"n_sc_multi_result\", \"label\": \"customer asks about timings / open today\"}, {\"id\": \"e17\", \"to\": \"n_sc_hours_faq\", \"from\": \"n_sc_contact\", \"label\": \"customer asks about timings / open today\"}, {\"id\": \"e18\", \"to\": \"n_sc_contact\", \"from\": \"n_sc_hours_faq\", \"label\": \"pending contact-number offer resumes\"}, {\"id\": \"e19\", \"to\": \"n_closing_check\", \"from\": \"n_sc_hours_faq\", \"label\": \"no pending step\"}, {\"id\": \"e20\", \"to\": \"n_closing_check\", \"from\": \"n_sc_contact\", \"label\": \"contact shared\"}, {\"id\": \"e21\", \"to\": \"n_wty_ask\", \"from\": \"n_intent\", \"label\": \"warranty_general_faq; no specific question in triggering utterance\"}, {\"id\": \"e22\", \"to\": \"n_wty_match\", \"from\": \"n_intent\", \"label\": \"warranty_general_faq; question already stated in triggering utterance\"}, {\"id\": \"e23\", \"to\": \"n_wty_match\", \"from\": \"n_wty_ask\", \"label\": \"question captured\"}, {\"id\": \"e24\", \"to\": \"n_wty_answer\", \"from\": \"n_wty_match\", \"label\": \"matched a knowledge-base entry\"}, {\"id\": \"e25\", \"to\": \"n_wty_case_specific\", \"from\": \"n_wty_match\", \"label\": \"case_specific_confirmation_request\"}, {\"id\": \"e26\", \"to\": \"n_wty_unmatched\", \"from\": \"n_wty_match\", \"label\": \"unmatched_or_out_of_scope; first attempt\"}, {\"id\": \"e27\", \"to\": \"n_wty_followup\", \"from\": \"n_wty_answer\", \"label\": \"answer given\"}, {\"id\": \"e28\", \"to\": \"n_wty_case_redirect\", \"from\": \"n_wty_case_specific\", \"label\": \"guardrail response given\"}, {\"id\": \"e29\", \"to\": \"n_sc_location\", \"from\": \"n_wty_case_redirect\", \"label\": \"customer wants service centre location\"}, {\"id\": \"e30\", \"to\": \"n_wty_followup\", \"from\": \"n_wty_case_redirect\", \"label\": \"customer declines redirect\"}, {\"id\": \"e31\", \"to\": \"n_wty_match\", \"from\": \"n_wty_unmatched\", \"label\": \"rephrased; retry match\"}, {\"id\": \"e32\", \"to\": \"n_wty_escalate\", \"from\": \"n_wty_unmatched\", \"label\": \"second consecutive unmatched\"}, {\"id\": \"e33\", \"to\": \"n_wty_match\", \"from\": \"n_wty_followup\", \"label\": \"reply is itself a new warranty question (barge-in)\"}, {\"id\": \"e34\", \"to\": \"n_closing_check\", \"from\": \"n_wty_followup\", \"label\": \"declined/no more questions\"}, {\"id\": \"e35\", \"to\": \"n_sc_end\", \"from\": \"n_closing_check\", \"label\": \"customer declines\"}, {\"id\": \"e36\", \"to\": \"n_sc_location\", \"from\": \"n_closing_check\", \"label\": \"accepts; new request already states service_centre_details\"}, {\"id\": \"e37\", \"to\": \"n_wty_ask\", \"from\": \"n_closing_check\", \"label\": \"accepts; new request already states warranty_general_faq (no question in same reply)\"}, {\"id\": \"e38\", \"to\": \"n_wty_match\", \"from\": \"n_closing_check\", \"label\": \"accepts; specific warranty question already stated in same reply\"}, {\"id\": \"e39\", \"to\": \"n_reopen\", \"from\": \"n_closing_check\", \"label\": \"accepts but does not specify a request\"}, {\"id\": \"e40\", \"to\": \"n_intent\", \"from\": \"n_reopen\", \"label\": \"wait for customer\'s next request\"}]','[]','2026-09-22 15:49:29','2026-09-22 17:37:28','usr_932efc2d9b3a','usr_932efc2d9b3a',0,NULL,NULL),('wf_1782b0d565f6','tn-001','bot_7a8a8dfc7f55','support journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-08-04 16:51:14','2026-08-04 16:51:14','usr-demo-priya',NULL,0,NULL,NULL),('wf_1869b624eb6a','tn_ff6be580b6d9','bot_8326bfad57d3','MPOnline — placeholder (bot is prompt-only)',9,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Not used — this bot is prompt-only\", \"config\": {}}, {\"x\": 300, \"y\": 40, \"id\": \"n_end\", \"kind\": \"end\", \"label\": \"Not used — this bot is prompt-only\", \"config\": {}}]','[{\"id\": \"e_start__end\", \"to\": \"n_end\", \"from\": \"n_start\"}]','[]','2026-09-21 15:54:08','2026-09-21 17:26:23','usr_dbd0c45cc799','usr_60d282b21092',0,NULL,NULL),('wf_20742af22e12','tn-001','bot_97f0cfd60536','x journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-20 12:57:17','2026-07-20 12:57:17','usr-demo-priya',NULL,0,NULL,NULL),('wf_23061ffd23d8','tn-001','bot_c4079035d1f8','support journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-08-04 16:50:46','2026-08-04 16:50:46','usr-demo-priya',NULL,0,NULL,NULL),('wf_23573edf219e','tn_22a809aecf66','bot_fb88841de0f7','0 to 07 collection call (Male)',8,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Outbound call connected\", \"config\": null}, {\"x\": 40, \"y\": 150, \"id\": \"n_push\", \"kind\": \"intent\", \"label\": \"Rung 1: pay-now push (UPI on call)\", \"config\": {\"prompt\": \"आपके प्रोफ़ाइल पर एक लोन ओवरड्यू दिख रहा है, जिसका कुल बकाया ₹2,000 है और यह 5 दिनों से ओवरड्यू है। कॉल पर रहते हुए UPI के ज़रिए अभी पेमेंट पूरा कर दीजिए, ताकि आपका प्रोफ़ाइल तुरंत अपडेट हो जाए। क्या आप अभी पेमेंट करेंगे?\", \"responseMode\": \"fixed\", \"responseDirective\": \"State the overdue amount and overdue days, ask for payment now through UPI, and mention immediate profile update. Use the caller current language.\", \"responseMustInclude\": [\"₹2000\", \"5\", \"UPI\"]}}, {\"x\": 40, \"y\": 260, \"id\": \"n_benefits\", \"kind\": \"intent\", \"label\": \"Rung 2: benefits (limit / BHIM / Paytm)\", \"config\": {\"prompt\": \"अगर आप अभी कॉल पर पेमेंट पूरा करते हैं, तो आपकी क्रेडिट लिमिट धीरे-धीरे ₹50,000 तक बढ़ने की संभावना है। BHIM UPI से पेमेंट पर ₹40 तक का डिस्काउंट मिल सकता है। Paytm UPI से ₹10 से ₹300 तक का कैशबैक और महीने में एक बार ₹2,000 तक का Paytm वाउचर मिलने की संभावना है। क्या आप अभी UPI से पेमेंट करेंगे?\", \"responseMode\": \"fixed\", \"responseDirective\": \"Explain every approved credit-limit, BHIM and Paytm benefit with all amounts, then ask whether the caller can pay now. Use the caller current language.\", \"responseMustInclude\": [\"₹50,000\", \"BHIM\", \"₹40\", \"Paytm\", \"₹10\", \"₹300\", \"₹2,000\"]}}, {\"x\": 40, \"y\": 370, \"id\": \"n_promise\", \"kind\": \"intent\", \"label\": \"Rung 3: previous interaction & promise\", \"config\": {\"prompt\": \"सिस्टम रिकॉर्ड के अनुसार, पहले भी आपसे पेमेंट के बारे में बात हुई थी और आपने पेमेंट करने का वादा किया था, लेकिन अभी तक पेमेंट नहीं मिला है। आपने पहले कई बार समय पर लोन चुकाया है। कृपया अभी भी पेमेंट कर दीजिए, ताकि अतिरिक्त पेनल्टी या चार्ज न जुड़ें। क्या आप अभी पेमेंट करेंगे?\", \"responseMode\": \"fixed\", \"responseDirective\": \"Explain the previous missed promise and positive repayment history without inventing details, then ask for payment now. Use the caller current language.\"}}, {\"x\": 40, \"y\": 480, \"id\": \"n_funds\", \"kind\": \"intent\", \"label\": \"Rung 4: arrange funds (savings / friends & family)\", \"config\": {\"prompt\": \"अगर संभव हो, तो अपनी उपलब्ध सेविंग्स से लोन का पेमेंट कर दीजिए। आप किसी दोस्त या परिवार के सदस्य से व्यवस्था करके भी पेमेंट कर सकते हैं, ताकि अतिरिक्त पेनल्टी से बच सकें। क्या आप पेमेंट की व्यवस्था कर पाएँगे?\", \"responseMode\": \"fixed\", \"responseDirective\": \"Explain the approved savings or friends-and-family arrangement option respectfully, then ask whether funds can be arranged. Use the caller current language.\"}}, {\"x\": 40, \"y\": 590, \"id\": \"n_penalty\", \"kind\": \"intent\", \"label\": \"Rung 5: penalty consequences\", \"config\": {\"prompt\": \"ड्यू डेट पर पेमेंट न करने से पेनल्टी रोज़ बढ़ सकती है और अतिरिक्त चार्ज जुड़ते रहते हैं। अतिरिक्त चार्ज से बचने के लिए कृपया अभी पेमेंट पूरा कर दीजिए। क्या आप अभी पेमेंट करेंगे?\", \"responseMode\": \"fixed\", \"responseDirective\": \"Explain that daily penalty and extra charges increase, then ask for payment now. Use the caller current language.\"}}, {\"x\": 40, \"y\": 700, \"id\": \"n_cibil\", \"kind\": \"intent\", \"label\": \"Rung 6: CIBIL consequences\", \"config\": {\"prompt\": \"समय पर पेमेंट न करने से आपका CIBIL स्कोर प्रभावित हो सकता है। मेडिकल या परिवार की इमरजेंसी में भविष्य में लोन की ज़रूरत पड़ सकती है, और कम CIBIL स्कोर होने पर लोन मिलने में कठिनाई या अधिक ब्याज लग सकता है। कृपया अभी पेमेंट करके अपना CIBIL सुरक्षित रखिए। क्या आप पेमेंट करेंगे?\", \"responseMode\": \"fixed\", \"responseDirective\": \"Explain the approved CIBIL and emergency-loan consequences without threats, then ask for payment. Use the caller current language.\"}}, {\"x\": 40, \"y\": 810, \"id\": \"n_refuse_end\", \"kind\": \"end\", \"label\": \"Refusal close\", \"config\": {\"text\": \"ठीक है, मैंने आपकी बात नोट कर ली है। कृपया याद रखिए कि जल्द पेमेंट करने से अतिरिक्त पेनल्टी और CIBIL पर असर से बचा जा सकता है। कृपया आज ही एमपॉकेट ऐप में पेमेंट करने की कोशिश कीजिए। एमपॉकेट को समय देने के लिए धन्यवाद। आपका दिन शुभ हो!\", \"responseMode\": \"fixed\", \"responseDirective\": \"Close respectfully after the final refusal, mentioning penalty/CIBIL consequences once and the app payment option. Use the caller current language.\"}}, {\"x\": 360, \"y\": 150, \"id\": \"n_ptype\", \"kind\": \"ask\", \"label\": \"Full or partial payment\", \"config\": {\"question\": \"बहुत अच्छा। क्या आप पूरा बकाया पेमेंट करेंगे या पार्शियल पेमेंट करेंगे?\", \"synonyms\": {\"full\": [\"poora\", \"pura\", \"puri\", \"complete\", \"whole\", \"saara\", \"sara\", \"full\", \"पूरा\", \"पूरी\", \"सारा\", \"पूर्ण\"], \"partial\": [\"partial\", \"part payment\", \"aadha\", \"adha\", \"half\", \"thoda\", \"installment\", \"instalment\", \"kisht\", \"आधा\", \"आधी\", \"थोड़ा\", \"थोड़ी\", \"किस्त\", \"किश्त\"]}, \"variable\": \"payment_type\", \"entityType\": \"list\", \"responseMode\": \"fixed\", \"responseDirective\": \"Ask whether the caller will make full or partial payment. Use the caller current language and preserve both options.\"}}, {\"x\": 360, \"y\": 260, \"id\": \"n_mop\", \"kind\": \"ask\", \"label\": \"Mode of payment\", \"config\": {\"question\": \"आपका पेमेंट किस माध्यम से होगा—Debit Card या UPI?\", \"synonyms\": {\"UPI\": [\"upi\", \"bhim\", \"paytm\", \"gpay\", \"google pay\", \"phonepe\", \"phone pe\", \"qr\", \"यूपीआई\", \"यू पी आई\", \"भीम\", \"पेटीएम\", \"फोनपे\", \"फोन पे\", \"गूगल पे\", \"क्यूआर\"], \"Debit Card\": [\"debit\", \"card\", \"atm\", \"डेबिट\", \"कार्ड\", \"एटीएम\"]}, \"variable\": \"payment_method\", \"entityType\": \"list\", \"responseMode\": \"fixed\", \"responseDirective\": \"Ask whether payment will be through Debit Card or UPI. Use the caller current language and preserve both options.\", \"responseMustInclude\": [\"Debit Card\", \"UPI\"]}}, {\"x\": 360, \"y\": 370, \"id\": \"n_guide\", \"kind\": \"message\", \"label\": \"Payment guidance\", \"config\": {\"text\": \"धन्यवाद। कृपया एमपॉकेट ऐप खोलकर अपना पेमेंट पूरा कर दीजिए। BHIM UPI या Paytm UPI से पेमेंट करने पर लागू डिस्काउंट या कैशबैक मिल सकता है। पेमेंट सफल होने के बाद आपका प्रोफ़ाइल अपडेट हो जाएगा।\", \"responseMode\": \"fixed\", \"responseDirective\": \"Guide the caller to pay safely in the एमपॉकेट app, mention applicable UPI benefits and profile update, and never claim payment completed. Use the caller current language.\", \"responseMustInclude\": [\"एमपॉकेट\"]}}, {\"x\": 360, \"y\": 480, \"id\": \"n_close\", \"kind\": \"end\", \"label\": \"Close call\", \"config\": {\"text\": \"एमपॉकेट को समय देने के लिए धन्यवाद। आपका दिन शुभ हो!\", \"responseMode\": \"fixed\", \"responseDirective\": \"Thank the caller and close politely in the caller current language.\", \"responseMustInclude\": [\"एमपॉकेट\"]}}, {\"x\": 660, \"y\": 150, \"id\": \"n_callback\", \"kind\": \"end\", \"label\": \"Callback close\", \"config\": {\"text\": \"कोई बात नहीं, हम आपको बाद में कॉल कर लेंगे। कृपया जितनी जल्दी संभव हो, एमपॉकेट ऐप से अपना पेमेंट पूरा कर दीजिए, ताकि अतिरिक्त चार्ज से बच सकें। धन्यवाद। आपका दिन शुभ हो!\", \"responseMode\": \"fixed\", \"responseDirective\": \"Confirm the callback and close politely without repeating the full pitch. Use the caller current language.\"}}, {\"x\": 660, \"y\": 260, \"id\": \"n_wrong\", \"kind\": \"end\", \"label\": \"Wrong person close\", \"config\": {\"text\": \"माफ़ कीजिए, लगता है यह कॉल गलत नंबर पर लग गई है। आपका समय लेने के लिए खेद है। धन्यवाद। आपका दिन शुभ हो!\", \"responseMode\": \"fixed\", \"responseDirective\": \"Apologize for the wrong person or number, reveal no loan details, and close in the caller current language.\"}}, {\"x\": 660, \"y\": 370, \"id\": \"n_paid\", \"kind\": \"message\", \"label\": \"Already paid — verify\", \"config\": {\"text\": \"अगर आपने पेमेंट कर दिया है, तो धन्यवाद। मैं आपको हमारे एजेंट से कनेक्ट कर रहा हूँ, जो आपके पेमेंट की पुष्टि करेंगे। कृपया लाइन पर बने रहिए।\", \"responseMode\": \"fixed\", \"responseDirective\": \"Acknowledge the already-paid claim without treating it as verified, and say an agent will verify it. Use the caller current language.\"}}, {\"x\": 660, \"y\": 480, \"id\": \"n_agent\", \"kind\": \"message\", \"label\": \"Agent handover\", \"config\": {\"text\": \"मैं आपको हमारे एजेंट से कनेक्ट कर रहा हूँ। कृपया लाइन पर बने रहिए।\", \"responseMode\": \"fixed\", \"responseDirective\": \"Tell the caller they are being connected to an agent. Use the caller current language.\"}}, {\"x\": 660, \"y\": 590, \"id\": \"n_hardship\", \"kind\": \"intent\", \"label\": \"Financial or medical hardship\", \"config\": {\"prompt\": \"मैं आपकी बात समझ रहा हूँ। अभी पैसे उपलब्ध न होना एक वास्तविक परेशानी हो सकती है। मैं आप पर पेमेंट के लिए दबाव नहीं डालूँगा। क्या आप चाहेंगे कि हम बाद में कॉल करें, या मैं आपको सपोर्ट एजेंट से कनेक्ट करूँ?\", \"responseMode\": \"fixed\", \"responseDirective\": \"Acknowledge financial or medical hardship empathetically without pressure, then offer either a later callback or a support agent. Use the caller current language.\"}}, {\"x\": 920, \"y\": 590, \"id\": \"n_hardship_close\", \"kind\": \"end\", \"label\": \"Hardship — respectful close\", \"config\": {\"text\": \"ठीक है, मैं समझ गया हूँ। आप पहले अपनी ज़रूरी आवश्यकताओं का ध्यान रखिए। जब संभव हो, एमपॉकेट ऐप में उपलब्ध रीपेमेंट विकल्प देख सकते हैं। धन्यवाद। आपका दिन शुभ हो।\", \"responseMode\": \"fixed\", \"responseDirective\": \"Close respectfully after hardship and do not pressure the caller. Use the caller current language.\"}}, {\"x\": 920, \"y\": 480, \"id\": \"n_agent_transfer\", \"kind\": \"handover\", \"label\": \"Complete agent transfer\", \"config\": {}}]','[{\"id\": \"e_hardship_paid\", \"to\": \"n_paid\", \"from\": \"n_hardship\", \"label\": \"already paid,payment already,paid,kar diya,kar di,पेमेंट कर दिया,पेमेंट कर दी\"}, {\"id\": \"e_hardship_pay\", \"to\": \"n_ptype\", \"from\": \"n_hardship\", \"label\": \"payment,pay,partial,full,UPI,debit,card,ready to pay,I can pay,abhi pay,kar dunga,पेमेंट,भुगतान,यूपीआई,डेबिट,कार्ड\"}, {\"id\": \"e_start\", \"to\": \"n_push\", \"from\": \"n_start\"}, {\"id\": \"e_push_wrong\", \"to\": \"n_wrong\", \"from\": \"n_push\", \"label\": \"galat number,wrong number,main woh nahi,mai woh nahi,koi aur,is naam,mera loan nahi,loan liya hi nahi