, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-17 18:33:21','2026-07-17 18:33:21','usr_76a272d94ac9',NULL,0,NULL,NULL),('wf_6d8a6bf5446b','tn-001','bot_447e68933074','x journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-20 12:57:48','2026-07-20 12:57:48','usr-demo-priya',NULL,0,NULL,NULL),('wf_706dbcb29913','tn_9677acfb2c93','bot_c213549e0df4','Collections plan',2,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\", \"config\": {\"text\": \"I can set up a payment plan for you.\"}}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"ask\", \"label\": \"Ask amount\", \"config\": {\"question\": \"How much can you pay per month?\", \"variable\": \"amount\", \"entityType\": \"number\"}}, {\"x\": 260, \"y\": 260, \"id\": \"n4\", \"kind\": \"condition\", \"label\": \"Check amount\", \"config\": {\"value\": 1000, \"operator\": \"gte\", \"variable\": \"amount\"}}, {\"x\": 480, \"y\": 200, \"id\": \"n5\", \"kind\": \"end\", \"label\": \"End call\", \"config\": {\"text\": \"Your plan is registered. Goodbye!\"}}, {\"x\": 480, \"y\": 330, \"id\": \"n6\", \"kind\": \"handover\", \"label\": \"Agent\", \"config\": {\"text\": \"An agent needs to approve that amount.\"}}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}, {\"id\": \"e3\", \"to\": \"n4\", \"from\": \"n3\"}, {\"id\": \"e4\", \"to\": \"n5\", \"from\": \"n4\", \"label\": \"true\"}, {\"id\": \"e5\", \"to\": \"n6\", \"from\": \"n4\", \"label\": \"false\"}]','[]','2026-08-17 15:44:36','2026-08-17 15:44:37','usr_4ff2e2d7c490','usr_4ff2e2d7c490',0,NULL,NULL),('wf_771597e53d86','tn_22a809aecf66','bot_b97b33667066','DPD 8-30 collection call',2,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Outbound call connected\"}, {\"x\": 40, \"y\": 150, \"id\": \"n_push\", \"kind\": \"intent\", \"label\": \"Rung 1: push\", \"config\": {\"prompt\": \"Aap call par rehte hue hi UPI ke through abhi payment complete kar dijiye, taaki hum turant aapki help kar sakein aur payment se related koi dikkat na ho. Saath hi aapka profile bhi turant update ho jayega. Kya aap abhi payment karenge?\"}}, {\"x\": 40, \"y\": 260, \"id\": \"n_benefits\", \"kind\": \"intent\", \"label\": \"Rung 2: benefits\", \"config\": {\"prompt\": \"Ek achhi baat bata dun — agar aap abhi call par payment complete karte hain, toh aapki credit limit gradually ₹50,000 tak badhne ke high chances hain. BHIM UPI se payment par ₹40 tak ka discount mil sakta hai, aur Paytm UPI se ₹10 se ₹300 tak ka cashback aur mahine mein ek baar ₹2,000 tak ka Paytm voucher milne ka chance bhi hai. Toh kya aap abhi UPI se payment complete karenge?\"}}, {\"x\": 40, \"y\": 370, \"id\": \"n_promise_funds\", \"kind\": \"intent\", \"label\": \"Rung 3: promise_funds\", \"config\": {\"prompt\": \"System records ke hisaab se pehle bhi aapse payment ke baare mein baat hui thi aur aapne payment ka promise kiya tha, lekin abhi tak payment receive nahi hui hai. Aapne pehle kai baar bina kisi extra charges ke time par repay kiya hai. Aap apni savings se, ya kisi friend ya family se arrange karke bhi payment kar sakte hain — isse aapko koi penalty nahi deni hogi. Kya aap payment ka intezaam kar lenge?\"}}, {\"x\": 40, \"y\": 480, \"id\": \"n_penalty\", \"kind\": \"intent\", \"label\": \"Rung 4: penalty\", \"config\": {\"prompt\": \"Main aapko inform karna chahta hun ki due date par payment na karne se penalty daily badhti hai aur extra charges lagte rehte hain. Extra charges avoid karne ke liye abhi payment complete kar dijiye. Kya aap abhi payment karenge?\"}}, {\"x\": 40, \"y\": 590, \"id\": \"n_cibil\", \"kind\": \"intent\", \"label\": \"Rung 5: cibil\", \"config\": {\"prompt\": \"Ek aur zaroori baat — time par repayment na karne se aapka CIBIL score impact hota hai, aur aaj ke time mein CIBIL bahut important hai. Emergency mein — jaise medical ya family needs — loan ki zarurat kabhi bhi pad sakti hai. Agar CIBIL low hoga toh loan milne mein dikkat ho sakti hai, ya interest rate kaafi high ho sakta hai. Isliye request hai ki abhi payment complete kar dijiye aur apna CIBIL safe rakhiye. Kya aap payment karenge?\"}}, {\"x\": 40, \"y\": 700, \"id\": \"n_limit\", \"kind\": \"intent\", \"label\": \"Rung 6: limit\", \"config\": {\"prompt\": \"Time par payment na karne se aapka credit limit decrease ho sakta hai. Lekin agar aap time par repayment karte hain, toh aapka credit limit gradually ₹50,000 tak increase ho sakta hai. Kya aap abhi payment complete karenge?\"}}, {\"x\": 360, \"y\": 150, \"id\": \"n_ptype\", \"kind\": \"ask\", \"label\": \"Full or partial payment\", \"config\": {\"question\": \"Bahut achha! Kya aap apna poora overdue amount pay karenge, ya partial payment karenge?\", \"synonyms\": {\"full\": [\"poora\", \"pura\", \"puri\", \"complete\", \"whole\", \"saara\", \"sara\", \"full\", \"पूरा\", \"पूरी\", \"सारा\", \"पूर्ण\"], \"partial\": [\"partial\", \"part payment\", \"aadha\", \"adha\", \"half\", \"thoda\", \"installment\", \"instalment\", \"kisht\", \"आधा\", \"आधी\", \"थोड़ा\", \"थोड़ी\", \"किस्त\", \"किश्त\"]}, \"variable\": \"payment_type\", \"entityType\": \"list\"}}, {\"x\": 360, \"y\": 260, \"id\": \"n_mop\", \"kind\": \"ask\", \"label\": \"Mode of payment\", \"config\": {\"question\": \"Kaunse madhyam se aapka payment hoga – Debit Card ya UPI?\", \"synonyms\": {\"UPI\": [\"upi\", \"bhim\", \"paytm\", \"gpay\", \"google pay\", \"phonepe\", \"phone pe\", \"qr\", \"यूपीआई\", \"यू पी आई\", \"भीम\", \"पेटीएम\", \"फोनपे\", \"फोन पे\", \"गूगल पे\", \"क्यूआर\"], \"Debit Card\": [\"debit\", \"card\", \"atm\", \"डेबिट\", \"कार्ड\", \"एटीएम\"]}, \"variable\": \"payment_method\", \"entityType\": \"list\"}}, {\"x\": 360, \"y\": 370, \"id\": \"n_guide\", \"kind\": \"message\", \"label\": \"Payment guidance\", \"config\": {\"text\": \"Dhanyavaad! Kripya mPokket app kholkar apna payment abhi complete kar dijiye. BHIM UPI ya Paytm UPI se payment karne par discount ya cashback milne ke chances bhi hain. Payment complete hote hi aapka profile turant update ho jayega aur koi extra penalty charges nahi lagenge. Main call par kabhi card number, PIN ya OTP nahi maangta — yeh details kisi ke saath share na karein.\"}}, {\"x\": 360, \"y\": 480, \"id\": \"n_close\", \"kind\": \"end\", \"label\": \"Close call\", \"config\": {\"text\": \"mPokket mein samay dene ke liye dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 40, \"y\": 810, \"id\": \"n_refuse_end\", \"kind\": \"end\", \"label\": \"Refusal close\", \"config\": {\"text\": \"Theek hai, main aapki baat note kar raha hun. Kripya yaad rakhiye — jitni jaldi aap payment complete karenge, utna hi aap extra penalty aur CIBIL impact se bachenge. Kripya aaj hi mPokket app se apna payment complete karne ki koshish kijiye. mPokket mein samay dene ke liye dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 660, \"y\": 150, \"id\": \"n_callback\", \"kind\": \"end\", \"label\": \"Callback close\", \"config\": {\"text\": \"Koi baat nahi, hum aapko baad mein call kar lenge. Kripya jitni jaldi ho sake mPokket app se apna payment complete kar dijiye, taaki koi extra charges na lagen. Dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 660, \"y\": 260, \"id\": \"n_wrong\", \"kind\": \"end\", \"label\": \"Wrong person close\", \"config\": {\"text\": \"Maaf kijiye, lagta hai yeh call galat number par lag gayi. Aapka samay lene ke liye khed hai. Dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 660, \"y\": 370, \"id\": \"n_paid\", \"kind\": \"handover\", \"label\": \"Already paid — verify\", \"config\": {\"text\": \"Agar aapne payment already complete kar di hai, toh dhanyavaad! Main aapko hamare agent se connect kar raha hun jo aapki payment verify kar denge. Kripya line par bane rahiye.\"}}, {\"x\": 660, \"y\": 480, \"id\": \"n_agent\", \"kind\": \"handover\", \"label\": \"Agent handover\", \"config\": {\"text\": \"Main aapko hamare ek agent se connect kar raha hun. Kripya line par bane rahiye.\"}}]','[{\"id\": \"e_start\", \"to\": \"n_push\", \"from\": \"n_start\"}, {\"id\": \"e_push_paid\", \"to\": \"n_paid\", \"from\": \"n_push\", \"label\": \"paid,already,kar di,kar diya,kar chuka,kar chuki,ho chuki,ho chuka,ho gaya,ho gayi,kat gaya,kat gayi,कर दी,कर दिया,कर चुका,हो चुकी,हो चुका,हो गया,हो गई,कट गया,कट गई\"}, {\"id\": \"e_push_wrong\", \"to\": \"n_wrong\", \"from\": \"n_push\", \"label\": \"galat number,wrong number,main woh nahi,mai woh nahi,koi aur,is naam,mera loan nahi,loan liya hi nahi,गलत नंबर,मैं वो नहीं,कोई और,इस नाम,मेरा लोन नहीं\"}, {\"id\": \"e_push_cb\", \"to\": \"n_callback\", \"from\": \"n_push\", \"label\": \"busy,meeting,call back,callback,baad mein call,call karna,drive,gaadi,vyast,बाद में कॉल,कॉल करना,व्यस्त,मीटिंग,गाड़ी\"}, {\"id\": \"e_push_agent\", \"to\": \"n_agent\", \"from\": \"n_push\", \"label\": \"agent,customer care,insaan,supervisor,manager,adhikari,एजेंट,कस्टमर केयर,इंसान,सुपरवाइज़र,मैनेजर\"}, {\"id\": \"e_push_refuse\", \"to\": \"n_benefits\", \"from\": \"n_push\", \"label\": \"nahi,nahin,paise,dikkat,problem,mushkil,baad,kal,parso,salary,agle,pagar,tankhwah,नहीं,नही,पैसे,पैसा,दिक्कत,मुश्किल,बाद,कल,परसों,सैलरी,अगले\"}, {\"id\": \"e_push_agree\", \"to\": \"n_ptype\", \"from\": \"n_push\", \"label\": \"haan,yes,okay,theek,bilkul,zaroor,jarur,taiyar,ready,kar deta,kar dunga,kar doonga,karunga,karungi,upi,debit,card,हाँ,हां,जी,ठीक,बिल्कुल,ज़रूर,जरूर,तैयार,कर देता,कर दूंगा,करूंगा,कर