\", \"to\": \"n38\", \"from\": \"n37\"}]','[]','2026-09-22 17:50:25','2026-09-22 18:11:48','usr_7038c713db74','usr_7038c713db74',0,NULL,NULL),('wf_a1c0ccea5b16','tn-001','bot_aa87f6514f59','Sarvam E2E Check journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-23 19:44:55','2026-07-23 19:44:55','usr-demo-priya',NULL,0,NULL,NULL),('wf_a43674e08daf','tn-001','bot_db7479ff9dd3','FAQ & information journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-21 19:28:51','2026-07-21 19:28:51','usr-demo-priya',NULL,0,NULL,NULL),('wf_a65d66483a33','tn_3385569203f7','bot_29baa65abeb7','Custom journey',17,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Inbound call starts\", \"config\": {}}, {\"x\": 40, \"y\": 150, \"id\": \"n_greeting\", \"kind\": \"message\", \"label\": \"Greeting\", \"config\": {\"text\": \"Hello, welcome to {brand_name} Service Support. I am your virtual service assistant. How may I help you today?\", \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 280, \"id\": \"n_intent\", \"kind\": \"intent\", \"label\": \"Identify customer intent\", \"config\": {\"allowedValues\": [\"service_centre_details\", \"warranty_general_faq\", \"unsupported_or_unclear\"]}}, {\"x\": 40, \"y\": 420, \"id\": \"n_sc_location\", \"kind\": \"ask\", \"label\": \"Capture PIN code or locality\", \"config\": {\"rule\": \"Accept EITHER pincode OR city/locality; accept both if given together. If already stated in the triggering utterance, extract and skip this node entirely.\", \"parse_to\": [\"service_centre_locator.pincode\", \"service_centre_locator.city\", \"service_centre_locator.locality\"], \"question\": \"Sure. Please tell me your PIN code or city so I can find the nearest authorised service centre.\", \"variable\": \"service_centre_locator.location_input\", \"condition\": \"pincode AND city AND locality are all unavailable\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 550, \"id\": \"n_sc_area_clarify\", \"kind\": \"ask\", \"label\": \"Area clarification (only if insufficient)\", \"config\": {\"rule\": \"Ask ONLY if the given city/PIN is genuinely insufficient for the lookup source. Ask once only.\", \"question\": \"Which area or locality should I check?\", \"variable\": \"service_centre_locator.locality\", \"condition\": \"city present AND locality/pincode still insufficient for lookup\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 680, \"id\": \"n_sc_search\", \"kind\": \"api\", \"label\": \"Search service centre directory\", \"config\": {\"rule\": \"Query against service_centre_master using whichever of pincode/city/locality is available. Never invent results. This node has NO standalone spoken output of its own: any optional filler line (e.g. \'Sure, let me check that.\') must be emitted fused into the SAME response as the immediate_next_node\'s message (n_sc_one_result / n_sc_multi_result), never as a separate turn that waits for the customer. Do not trigger silence_recovery on this node or in the gap before the next node fires.\", \"inputs\": {\"city\": \"service_centre_locator.city\", \"pincode\": \"service_centre_locator.pincode\", \"locality\": \"service_centre_locator.locality\"}, \"condition\": \"pincode OR (city AND locality) available\", \"connection\": \"service_centre_lookup\", \"on_failure\": \"n_sc_fail\", \"on_success\": \"immediate_next_node\", \"silence_recovery_enabled\": false, \"expects_customer_response\": false, \"backend_pending_is_not_customer_silence\": true}}, {\"x\": -260, \"y\": 820, \"id\": \"n_sc_one_result\", \"kind\": \"message\", \"label\": \"Announce single centre + offer contact\", \"config\": {\"rule\": \"Speak ONLY fields returned in service_centre_locator.results[0]. Offer the contact number as a question here — do not speak the number yet. Times: speak opening_time/closing_time exactly as their AM/PM value (e.g. \'9:30 AM to 7:00 PM\') even in Hindi/Hinglish output — never convert to \'baje\' phrasing, never say \'baje\' twice.\", \"format\": \"The nearest authorised service centre is {results[0].centre_name}, located at {results[0].address}. It is open {results[0].working_days} from {results[0].opening_time} to {results[0].closing_time}. Would you also like the contact number?\", \"tts_safe\": true, \"dynamic_source\": \"service_centre_locator.results\", \"expects_customer_response\": true}}, {\"x\": 40, \"y\": 820, \"id\": \"n_sc_multi_result\", \"kind\": \"message\", \"label\": \"Announce multiple centres + offer contact\", \"config\": {\"rule\": \"Limit to the 2-3 nearest returned results only. Speak ONLY fields returned by the API. Times: speak opening_time/closing_time exactly as their AM/PM value — never convert to \'baje\' phrasing, never say \'baje\' twice.\", \"format\": \"I found a few authorised service centres near you. The nearest is {results[0].centre_name} at {results[0].address}. Another option is {results[1].centre_name} at {results[1].address}. Would you like the contact details for either centre?\", \"tts_safe\": true, \"dynamic_source\": \"service_centre_locator.results\", \"expects_customer_response\": true}}, {\"x\": 340, \"y\": 820, \"id\": \"n_sc_fail\", \"kind\": \"handover\", \"label\": \"No centre found / lookup failure\", \"config\": {\"rule\": \"Never invent or suggest an unverified third-party centre.\", \"queue\": \"yamaha_customer_support\", \"condition\": \"no matching result or lookup failure\"}}, {\"x\": -100, \"y\": 950, \"id\": \"n_sc_contact\", \"kind\": \"message\", \"label\": \"Share contact number (separate turn)\", \"config\": {\"rule\": \"Only reached after customer confirms yes. Speak ONLY the phone_number field of the selected/only centre. Do not repeat address/hours here.\", \"format\": \"You can contact the centre on {selected_centre.phone_number}.\", \"tts_safe\": true, \"condition\": \"contact_number_offered=true AND customer confirmed yes\", \"dynamic_source\": \"service_centre_locator.selected_centre_index\"}}, {\"x\": -100, \"y\": 1070, \"id\": \"n_sc_hours_faq\", \"kind\": \"message\", \"label\": \"Working hours / open-today answer (re-entrant)\", \"config\": {\"rule\": \"Reachable at any point after a centre result exists, whenever the customer asks about timings or if it is open today. Only assert \'open now/today\' if a live open/closed status is available; otherwise state listed hours only. Times: speak opening_time/closing_time exactly as their AM/PM value — never convert to \'baje\' phrasing, never say \'baje\' twice.\", \"format\": \"The listed working hours are {selected_centre.working_days}, {selected_centre.opening_time} to {selected_centre.closing_time}.\", \"tts_safe\": true, \"dynamic_source\": \"service_centre_locator.selected_centre_index\", \"expects_customer_response\": false}}, {\"x\": -100, \"y\": 1190, \"id\": \"n_sc_end\", \"kind\": \"end\", \"label\": \"Service centre journey completed\", \"config\": {\"text\": \"Thank you for contacting {brand_name} Service Support. Have a good day.\"}}, {\"x\": 800, \"y\": 280, \"id\": \"n_unsupported\", \"kind\": \"handover\", \"label\": \"Unsupported request\", \"config\": {\"queue\": \"yamaha_customer_support\"}}, {\"x\": 500, \"y\": 1350, \"id\": \"n_wty_ask\", \"kind\": \"ask\", \"label\": \"Capture warranty question\", \"config\": {\"rule\": \"If the triggering utterance already contains a specific warranty question, extract it and skip this node entirely.\", \"question\": \"Sure. What would you like to know about your warranty?\", \"variable\": \"warranty_general_faq.raw_question_input\", \"condition\": \"no specific warranty question captured yet\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 500, \"y\": 1470, \"id\": \"n_wty_match\", \"kind\": \"intent\", \"label\": \"Match question against knowledge base\", \"config\": {\"rule\": \"Match by meaning/keywords, not exact wording, against warranty_faq_knowledge_base. Internal, instant operation — never end a turn on a filler alone; fuse any filler with the Step 3 answer in the same response, and never trigger silence-recovery around the match.\", \"variable\": \"warranty_general_faq.matched_topic_code\", \"allowedValues\": [\"WTY_WHAT_IS\", \"WTY_START_DATE\", \"WTY_DURATION\", \"WTY_PHYSICAL_DAMAGE\", \"WTY_LIQUID_DAMAGE\", \"WTY_FREE_REPAIR\", \"WTY_DOCUMENTS_REQUIRED\", \"WTY_LOST_INVOICE\", \"WTY_FULL_REPLACEMENT\", \"WTY_SPARE_PARTS\", \"WTY_AUTHORISED_CENTRE_ONLY\", \"WTY_REPAIR_EXTENDS_WARRANTY\", \"case_specific_confirmation_request\", \"unmatched_or_out_of_scope\"]}}, {\"x\": 380, \"y\": 1600, \"id\": \"n_wty_answer\", \"kind\": \"message\", \"label\": \"Speak matched knowledge-base answer\", \"config\": {\"rule\": \"Speak the stored approved_answer for warranty_general_faq.matched_topic_code word for word. Do not paraphrase, shorten, or add unapproved detail.\", \"format\": \"{matched_entry.approved_answer}\", \"tts_safe\": true, \"dynamic_source\": \"warranty_faq_knowledge_base\", \"expects_customer_response\": false}}, {\"x\": 380, \"y\": 1720, \"id\": \"n_wty_followup\", \"kind\": \"ask\", \"label\": \"Offer another warranty question\", \"config\": {\"rule\": \"If the reply is itself a new warranty question (barge-in), treat it as a new capture and route straight to n_wty_match instead of re-asking.\", \"question\": \"Is there anything else I can help you with?\", \"variable\": \"warranty_general_faq.followup_response\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 650, \"y\": 1600, \"id\": \"n_wty_case_specific\", \"kind\": \"message\", \"label\": \"Case-specific guardrail response\", \"config\": {\"rule\": \"Never infer eligibility from symptoms. Never soften this into an implied yes/no. Do not confirm or deny coverage. If the customer insists further after this line, add: \'I am unable to approve a warranty claim without the required verification.\' before moving to the redirect offer.\", \"text\": \"Warranty eligibility depends on the product, reported issue and applicable warranty terms. The authorised service team may need to inspect the product before confirming coverage.\", \"expects_customer_response\": false}}, {\"x\": 650, \"y\": 1720, \"id\": \"n_wty_case_redirect\", \"kind\": \"ask\", \"label\": \"Offer service-centre redirect\", \"config\": {\"question\": \"Would you like me to find the nearest authorised service centre for this?\", \"variable\": \"warranty_general_faq.redirect_to_service_centre_response\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 380, \"y\": 1470, \"id\": \"n_wty_unmatched\", \"kind\": \"ask\", \"label\": \"Unmatched / out-of-scope question\", \"config\": {\"rule\": \"Track warranty_general_faq.unmatched_attempts. Reset to 0 on any successful match.\", \"question\": \"I\'m sorry, I don\'t have information on that specific question. Could you rephrase it, or ask something else about your warranty?\", \"variable\": \"warranty_general_faq.raw_question_input\", \"condition\": \"no matching knowledge-base entry AND not a case-specific push\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 380, \"y\": 1350, \"id\": \"n_wty_escalate\", \"kind\": \"handover\", \"label\": \"Warranty FAQ fallback\", \"config\": {\"queue\": \"yamaha_customer_support\", \"condition\": \"second consecutive unmatched question, or customer asks for a human\"}}, {\"x\": 500, \"y\": 1840, \"id\": \"n_closing_check\", \"kind\": \"ask\", \"label\": \"Shared closing check (both flows)\", \"config\": {\"rule\": \"Reached whenever either flow reaches a natural completion point. If the customer\'s affirmative reply already states a new request, route straight into that flow (skip n_reopen). If affirmative but unspecified, go to n_reopen first. Never default into a specific flow just because it\'s the only other configured one.\", \"question\": \"Is there anything else I can help you with?\", \"variable\": \"closing_check.response\", \"silence_recovery_enabled\": true, \"expects_customer_response\": true}}, {\"x\": 650, \"y\": 1960, \"id\": \"n_reopen\", \"kind\": \"message\", \"label\": \"Re-open for a fresh intent\", \"config\": {\"text\": \"Sure, how can I help you?\", \"expects_customer_response\": true}}]','[{\"id\": \"e1\", \"to\": \"n_greeting\", \"from\": \"n_start\"}, {\"id\": \"e2\", \"to\": \"n_intent\", \"from\": \"n_greeting\"}, {\"id\": \"e3\", \"to\": \"n_sc_location\", \"from\": \"n_intent\", \"label\": \"service_centre_details\"}, {\"id\": \"e4\", \"to\": \"n_unsupported\", \"from\": \"n_intent\", \"label\": \"unsupported_or_unclear\"}, {\"id\": \"e5\", \"to\": \"n_sc_search\", \"from\": \"n_sc_location\", \"label\": \"pincode OR (city+locality) sufficient\"}, {\"id\": \"e6\", \"to\": \"n_sc_area_clarify\", \"from\": \"n_sc_location\", \"label\": \"city present but locality/pincode insufficient\"}, {\"id\": \"e7\", \"to\": \"n_sc_search\", \"from\": \"n_sc_area_clarify\", \"label\": \"locality captured\"}, {\"id\": \"e8\", \"to\": \"n_sc_one_result\", \"from\": \"n_sc_search\", \"label\": \"exactly 1 result; immediate transition\"}, {\"id\": \"e9\", \"to\": \"n_sc_multi_result\", \"from\": \"n_sc_search\", \"label\": \"2+ results; immediate transition\"}, {\"id\": \"e10\", \"to\": \"n_sc_fail\", \"from\": \"n_sc_search\", \"label\": \"0 results or lookup failure\"}, {\"id\": \"e11\", \"to\": \"n_sc_contact\", \"from\": \"n_sc_one_result\", \"label\": \"customer confirms yes\"}, {\"id\": \"e12\", \"to\": \"n_closing_check\", \"from\": \"n_sc_one_result\", \"label\": \"customer declines contact number\"}, {\"id\": \"e13\", \"to\": \"n_sc_contact\", \"from\": \"n_sc_multi_result\", \"label\": \"customer picks a centre and confirms yes\"}, {\"id\": \"e14\", \"to\": \"n_closing_check\", \"from\": \"n_sc_multi_result\", \"label\": \"customer declines contact number\"}, {\"id\": \"e15\", \"to\": \"n_sc_hours_faq\", \"from\": \"n_sc_one_result\", \"label\": \"customer asks about timings / open today\"}, {\"id\": \"e16\", \"to\": \"n_sc_hours_faq\", \"from\": \"n_sc_multi_result\", \"label\": \"customer asks about timings / open today\"}, {\"id\": \"e17\", \"to\": \"n_sc_hours_faq\", \"from\": \"n_sc_contact\", \"label\": \"customer asks about timings / open today\"}, {\"id\": \"e18\", \"to\": \"n_sc_contact\", \"from\": \"n_sc_hours_faq\", \"label\": \"pending contact-number offer resumes\"}, {\"id\": \"e19\", \"to\": \"n_closing_check\", \"from\": \"n_sc_hours_faq\", \"label\": \"no pending step\"}, {\"id\": \"e20\", \"to\": \"n_closing_check\", \"from\": \"n_sc_contact\", \"label\": \"contact shared\"}, {\"id\": \"e21\", \"to\": \"n_wty_ask\", \"from\": \"n_intent\", \"label\": \"warranty_general_faq; no specific question in triggering utterance\"}, {\"id\": \"e22\", \"to\": \"n_wty_match\", \"from\": \"n_intent\", \"label\": \"warranty_general_faq; question already stated in triggering utterance\"}, {\"id\": \"e23\", \"to\": \"n_wty_match\", \"from\": \"n_wty_ask\", \"label\": \"question captured\"}, {\"id\": \"e24\", \"to\": \"n_wty_answer\", \"from\": \"n_wty_match\", \"label\": \"matched a knowledge-base entry\"}, {\"id\": \"e25\", \"to\": \"n_wty_case_specific\", \"from\": \"n_wty_match\", \"label\": \"case_specific_confirmation_request\"}, {\"id\": \"e26\", \"to\": \"n_wty_unmatched\", \"from\": \"n_wty_match\", \"label\": \"unmatched_or_out_of_scope; first attempt\"}, {\"id\": \"e27\", \"to\": \"n_wty_followup\", \"from\": \"n_wty_answer\", \"label\": \"answer given\"}, {\"id\": \"e28\", \"to\": \"n_wty_case_redirect\", \"from\": \"n_wty_case_specific\", \"label\": \"guardrail response given\"}, {\"id\": \"e29\", \"to\": \"n_sc_location\", \"from\": \"n_wty_case_redirect\", \"label\": \"customer wants service centre location\"}, {\"id\": \"e30\", \"to\": \"n_wty_followup\", \"from\": \"n_wty_case_redirect\", \"label\": \"customer declines redirect\"}, {\"id\": \"e31\", \"to\": \"n_wty_match\", \"from\": \"n_wty_unmatched\", \"label\": \"rephrased; retry match\"}, {\"id\": \"e32\", \"to\": \"n_wty_escalate\", \"from\": \"n_wty_unmatched\", \"label\": \"second consecutive unmatched\"}, {\"id\": \"e33\", \"to\": \"n_wty_match\", \"from\": \"n_wty_followup\", \"label\": \"reply is itself a new warranty question (barge-in)\"}, {\"id\": \"e34\", \"to\": \"n_closing_check\", \"from\": \"n_wty_followup\", \"label\": \"declined/no more questions\"}, {\"id\": \"e35\", \"to\": \"n_sc_end\", \"from\": \"n_closing_check\", \"label\": \"customer declines\"}, {\"id\": \"e36\", \"to\": \"n_sc_location\", \"from\": \"n_closing_check\", \"label\": \"accepts; new request already states service_centre_details\"}, {\"id\": \"e37\", \"to\": \"n_wty_ask\", \"from\": \"n_closing_check\", \"label\": \"accepts; new request already states warranty_general_faq (no question in same reply)\"}, {\"id\": \"e38\", \"to\": \"n_wty_match\", \"from\": \"n_closing_check\", \"label\": \"accepts; specific warranty question already stated in same reply\"}, {\"id\": \"e39\", \"to\": \"n_reopen\", \"from\": \"n_closing_check\", \"label\": \"accepts but does not specify a request\"}, {\"id\": \"e40\", \"to\": \"n_intent\", \"from\": \"n_reopen\", \"label\": \"wait for customer\'s next request\"}]','[]','2026-09-22 18:04:56','2026-09-22 19:15:47','usr_513be86de7eb','usr_513be86de7eb',0,NULL,NULL),('wf_aabbc624a802','tn_c431c69c688c','bot_ff1bd1aa18ae','support journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-17 18:31:37','2026-07-17 18:31:37','usr_1c5d40cfff8e',NULL,0,NULL,NULL),('wf_adfb7e149ea1','tn_04250683f1b3','bot_3213a1508a96','Zepto partner deduction support',3,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 300, \"y\": 40, \"id\": \"n_ask_issue\", \"kind\": \"ask\", \"label\": \"Which concern?\", \"config\": {\"entity\": {\"dataType\": \"text\", \"synonyms\": {\"rto\": [\"return to origin\", \"r t o\", \"r.t.o\", \"rto\", \"order wapas store\", \"store pe wapas\", \"store par wapas\", \"wapas store\", \"आरटीओ\", \"आर टी ओ\", \"वापस स्टोर\", \"स्टोर पे वापस\", \"स्टोर पर वापस\"], \"mdnd\": [\"mark delivered but not delivered\", \"marked delivered but not delivered\", \"delivered but not delivered\", \"marked as delivered\", \"mark delivered\", \"marked delivered\", \"delivered dikha\", \"delivered show\", \"customer ko nahi mila\", \"customer ko mila nahi\", \"deliver nahi hua\", \"delivery nahi hui\", \"m d n d\", \"m.d.n.d\", \"mdnd\", \"एमडीएनडी\", \"एम डी एन डी\", \"डिलीवर दिखा\", \"डिलीवर नहीं हुआ\", \"डिलीवरी नहीं हुई\", \"कस्टमर को नहीं मिला\"], \"onboarding_fee\": [\"onboarding\", \"on boarding\", \"joining fee\", \"joining fees\", \"joining ka paisa\", \"joining ke paise\", \"joining amount\", \"registration fee\", \"ऑनबोर्डिंग\", \"ऑन बोर्डिंग\", \"जॉइनिंग\", \"जोइनिंग\", \"रजिस्ट्रेशन फीस\"], \"uniform_deduction\": [\"raincoat\", \"rain coat\", \"t-shirt\", \"t shirt\", \"tshirt\", \"bag\", \"uniform\", \"रेनकोट\", \"रेन कोट\", \"टीशर्ट\", \"टी-शर्ट\", \"टी शर्ट\", \"बैग\", \"यूनिफॉर्म\", \"यूनिफार्म\"]}, \"allowedValues\": [\"mdnd\", \"uniform_deduction\", \"onboarding_fee\", \"rto\"]}, \"question\": \"We are here to help you with your payout deduction concerns. Please tell me which concern you are calling about — is it Mark Delivered but Not Delivered, that is MDND; a Raincoat, T-shirt or Bag related deduction; an Onboarding Fee related deduction; or an RTO issue?\", \"variable\": \"issue_type\"}}, {\"x\": 560, \"y\": 40, \"id\": \"n_cond_mdnd\", \"kind\": \"condition\", \"label\": \"issue_type = mdnd?\", \"config\": {\"value\": \"mdnd\", \"operator\": \"equals\", \"variable\": \"issue_type\"}}, {\"x\": 820, \"y\": 40, \"id\": \"n_cond_uniform\", \"kind\": \"condition\", \"label\": \"issue_type = uniform_deduction?\", \"config\": {\"value\": \"uniform_deduction\", \"operator\": \"equals\", \"variable\": \"issue_type\"}}, {\"x\": 1080, \"y\": 40, \"id\": \"n_cond_onboarding\", \"kind\": \"condition\", \"label\": \"issue_type = onboarding_fee?\", \"config\": {\"value\": \"onboarding_fee\", \"operator\": \"equals\", \"variable\": \"issue_type\"}}, {\"x\": 1340, \"y\": 40, \"id\": \"n_cond_rto\", \"kind\": \"condition\", \"label\": \"issue_type = rto?\", \"config\": {\"value\": \"rto\", \"operator\": \"equals\", \"variable\": \"issue_type\"}}, {\"x\": 40, \"y\": 170, \"id\": \"n_msg_unknown\", \"kind\": \"message\", \"label\": \"Unrecognized concern\", \"config\": {\"text\": \"I want to make sure your concern reaches the right team, so let me connect you with a support executive.\"}}, {\"x\": 300, \"y\": 170, \"id\": \"n_m_greet\", \"kind\": \"message\", \"label\": \"M — script greeting\", \"config\": {\"text\": \"We are here to help you regarding the Mark Delivered but Not Delivered concern. Please help me with some of the enquiries.\"}}, {\"x\": 560, \"y\": 170, \"id\": \"n_m_ask_deduction_amount\", \"kind\": \"ask\", \"label\": \"M — deduction_amount\", \"config\": {\"question\": \"What is the deduction amount?\", \"variable\": \"m_deduction_amount\", \"entityType\": \"text\"}}, {\"x\": 820, \"y\": 170, \"id\": \"n_m_ask_order_last4\", \"kind\": \"ask\", \"label\": \"M — order_last4\", \"config\": {\"entity\": {\"dataType\": \"number\", \"regexPattern\": \"[0-9]{4}\"}, \"question\": \"What are the last 4 digits of the Order ID?\", \"variable\": \"m_order_last4\"}}, {\"x\": 1080, \"y\": 170, \"id\": \"n_m_ask_deduction_date\", \"kind\": \"ask\", \"label\": \"M — deduction_date\", \"config\": {\"question\": \"On which date or week was the deduction made?\", \"variable\": \"m_deduction_date\", \"entityType\": \"text\"}}, {\"x\": 1340, \"y\": 170, \"id\": \"n_m_ask_called_customer\", \"kind\": \"ask\", \"label\": \"M — called_customer\", \"config\": {\"question\": \"Did you call the customer before attempting the delivery?\", \"variable\": \"m_called_customer\", \"entityType\": \"text\"}}, {\"x\": 40, \"y\": 300, \"id\": \"n_m_ask_reached_location\", \"kind\": \"ask\", \"label\": \"M — reached_location\", \"config\": {\"question\": \"Did you reach the customer\'s location for the delivery?\", \"variable\": \"m_reached_location\", \"entityType\": \"text\"}}, {\"x\": 300, \"y\": 300, \"id\": \"n_m_ask_handover_recipient\", \"kind\": \"ask\", \"label\": \"M — handover_recipient\", \"config\": {\"question\": \"Did you hand over the product to the customer, the security guard, or someone else?\", \"variable\": \"m_handover_recipient\", \"entityType\": \"text\"}}, {\"x\": 560, \"y\": 300, \"id\": \"n_m_ask_cx_support_call\", \"kind\": \"ask\", \"label\": \"M — cx_support_call\", \"config\": {\"question\": \"Did you get a call from the CX support regarding the delivery?\", \"variable\": \"m_cx_support_call\", \"entityType\": \"text\"}}, {\"x\": 820, \"y\": 300, \"id\": \"n_m_api\", \"kind\": \"api\", \"label\": \"Register M concern\", \"config\": {\"te