"n6\", \"kind\": \"handover\", \"label\": \"Agent\", \"config\": {\"text\": \"An agent needs to approve that amount.\"}}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}, {\"id\": \"e3\", \"to\": \"n4\", \"from\": \"n3\"}, {\"id\": \"e4\", \"to\": \"n5\", \"from\": \"n4\", \"label\": \"true\"}, {\"id\": \"e5\", \"to\": \"n6\", \"from\": \"n4\", \"label\": \"false\"}]','[]','2026-08-18 15:36:14','2026-08-18 15:36:15','usr_b4d77264bb30','usr_b4d77264bb30',0,NULL,NULL),('wf_b5ef6e0e8b0e','tn-001','bot_8df1be4b6b89','Sarvam E2E Check journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-07-23 19:33:41','2026-07-23 19:33:41','usr-demo-priya',NULL,0,NULL,NULL);
INSERT INTO `workflows` VALUES ('wf_bb319e0f6fb5','tn_b8897f32d4aa','bot_ac634648c152','AU Bank debit card and account services',3,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Call starts\", \"config\": {\"behavior\": {\"version\": 1, \"max_node_steps\": 60}}}, {\"x\": 300, \"y\": 40, \"id\": \"n_cond_verified\", \"kind\": \"condition\", \"label\": \"Already verified?\", \"config\": {\"operator\": \"exists\", \"variable\": \"customer_verified\"}}, {\"x\": 560, \"y\": 40, \"id\": \"n_ask_mobile\", \"kind\": \"ask\", \"label\": \"Registered mobile number\", \"config\": {\"entity\": {\"pii\": true, \"dataType\": \"phone\", \"regexPattern\": \"(?<![0-9])(?:91|0)?([0-9]{10})(?![0-9])\"}, \"question\": \"Sure. For security purposes, please first tell me your registered mobile number.\", \"variable\": \"auth_mobile\", \"textByLanguage\": {\"hi\": \"जी ज़रूर। सुरक्षा के लिए, कृपया सबसे पहले अपना registered mobile number बताइए।\"}, \"unmatchedReply\": \"For your security, I need to verify you before I can help with account or card services. Please tell me your ten digit registered mobile number.\", \"unmatchedReplyByLanguage\": {\"hi\": \"आपकी सुरक्षा के लिए, account या card services में मदद करने से पहले मुझे आपको verify करना होगा। कृपया अपना दस अंकों का registered mobile number बताइए।\"}}}, {\"x\": 820, \"y\": 40, \"id\": \"n_ask_otp\", \"kind\": \"ask\", \"label\": \"Login OTP\", \"config\": {\"entity\": {\"pii\": true, \"dataType\": \"text\", \"regexPattern\": \"(?<![0-9])([0-9]{6})(?![0-9])\"}, \"question\": \"Thank you. An OTP has been sent to your registered mobile number. Please share the six digit code.\", \"variable\": \"auth_otp\", \"textByLanguage\": {\"hi\": \"धन्यवाद। आपके registered mobile number पर एक OTP भेजा गया है। कृपया छह अंकों का OTP बताइए।\"}, \"unmatchedReply\": \"To complete the verification, please say the six digit OTP sent to your registered mobile number.\", \"unmatchedReplyByLanguage\": {\"hi\": \"Verification पूरा करने के लिए, कृपया अपने registered mobile number पर आया छह अंकों का OTP बताइए।\"}}}, {\"x\": 1080, \"y\": 40, \"id\": \"n_msg_verified\", \"kind\": \"message\", \"label\": \"Identity verified\", \"config\": {\"text\": \"Your identity has been successfully verified.\", \"setSlots\": {\"customer_verified\": true}, \"textByLanguage\": {\"hi\": \"आपकी पहचान सफलतापूर्वक verify हो गई है।\"}}}, {\"x\": 1340, \"y\": 40, \"id\": \"n_msg_auth_failed\", \"kind\": \"message\", \"label\": \"Verification failed — close\", \"config\": {\"text\": \"I\'m sorry, I was unable to verify your details, so I cannot proceed with account or card services on this call. Please call again later. Thank you for calling AU Small Finance Bank.\", \"textByLanguage\": {\"hi\": \"माफ़ कीजिए, मैं आपकी details verify नहीं कर पाई, इसलिए इस call पर account या card services के साथ आगे नहीं बढ़ सकती। कृपया बाद में दोबारा call करें। AU Small Finance Bank को call करने के लिए धन्यवाद।\"}}}, {\"x\": 40, \"y\": 170, \"id\": \"n_hub_services\", \"kind\": \"intent\", \"label\": \"How may I assist you?\", \"config\": {\"prompt\": \"How may I assist you today?\", \"alsoCapture\": [{\"entity\": {\"dataType\": \"text\", \"synonymPatterns\": {\"n_handover\": [\"(?<![\\\\w\\\\u0900-\\\\u097f])(?:representative|customer\\\\ care|kisi\\\\ se\\\\ baat|कस्टमर\\\\ केयर|real\\\\ person|supervisor|insaan\\\\ se|executive|aadmi\\\\ se|इंसान\\\\ से|manager|मैनेजर|एजेंट|human|agent)\"], \"n_hub_stmt\": [\"\\\\A(?![\\\\s\\\\S]*\\\\bsms\\\\b)\\\\A(?![\\\\s\\\\S]*(?:mini|मिनी|last five|transaction history|ट्रांज़ैक्शन हिस्ट्री))\\\\A(?![\\\\s\\\\S]*(?:\\\\bdon[’\']?t\\\\b|\\\\bdo not\\\\b|\\\\bmat\\\\b|nahi chahiye|nahin chahiye|नहीं चाहिए|मत))(?![\\\\s\\\\S]*(?:\\\\b(?:charges?|fees?|cost|delivery|deliver|reference|interest|rate|kaise|kyun|kyu|kyon|kab|kaun|kahan|where|when|why|how\\\\s+(?:does|do|to|long)|which\\\\s+(?:number|mobile)|what\\\\s+(?:are|is)\\\\s+(?:the\\\\s+)?(?:charge|fee|cost))\\\\b|चार्ज|शुल्क|कितन