number\"}}, {\"x\": 260, \"y\": 260, \"id\": \"n4\", \"kind\": \"condition\", \"label\": \"Check amount\", \"config\": {\"value\": 1000, \"operator\": \"gte\", \"variable\": \"amount\"}}, {\"x\": 480, \"y\": 200, \"id\": \"n5\", \"kind\": \"end\", \"label\": \"End call\", \"config\": {\"text\": \"Your plan is registered. Goodbye!\"}}, {\"x\": 480, \"y\": 330, \"id\": \"n6\", \"kind\": \"handover\", \"label\": \"Agent\", \"config\": {\"text\": \"An agent needs to approve that amount.\"}}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}, {\"id\": \"e3\", \"to\": \"n4\", \"from\": \"n3\"}, {\"id\": \"e4\", \"to\": \"n5\", \"from\": \"n4\", \"label\": \"true\"}, {\"id\": \"e5\", \"to\": \"n6\", \"from\": \"n4\", \"label\": \"false\"}]','[]','2026-08-17 15:43:14','2026-08-17 15:43:15','usr_536bd4e516e9','usr_536bd4e516e9',0,NULL,NULL),('wf_c449f1421055','tn_620d5400d462','bot_71194477c0eb','Honasa order support journey',10,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Call starts\", \"config\": {}}, {\"x\": 300, \"y\": 40, \"id\": \"n_ask_order\", \"kind\": \"ask\", \"label\": \"Ask order ID / phone\", \"config\": {\"pattern\": \"(?<![0-9])([0-9]{10}|[0-9]{7})(?![0-9])\", \"question\": \"Sure — please share the exact seven-digit order ID slowly, one digit at a time, or the ten-digit mobile number registered with the order.\", \"variable\": \"order_ref\", \"entityType\": \"text\", \"unmatchedReply\": \"I haven\'t verified an order yet. Please repeat the exact seven-digit order ID slowly, one digit at a time, or share the ten-digit mobile number registered with the order.\"}}, {\"x\": 560, \"y\": 40, \"id\": \"n_api_lookup\", \"kind\": \"api\", \"label\": \"Order Lookup API\", \"config\": {\"text\": \"Thank you! Give me a moment while I pull up your order.\", \"connection\": \"Honasa Order Lookup\"}}, {\"x\": 820, \"y\": 40, \"id\": \"n_msg_notfound\", \"kind\": \"message\", \"label\": \"Order not found\", \"config\": {\"text\": \"I\'m sorry — I couldn\'t find an order with those details in our system.\"}}, {\"x\": 1080, \"y\": 40, \"id\": \"n_ask_order2\", \"kind\": \"ask\", \"label\": \"Re-ask order ID / phone\", \"config\": {\"pattern\": \"(?<![0-9])([0-9]{10}|[0-9]{7})(?![0-9])\", \"question\": \"Please double-check the confirmation message and repeat the exact seven-digit order ID slowly, one digit at a time, or share the ten-digit registered mobile number.\", \"variable\": \"order_ref2\", \"entityType\": \"text\", \"unmatchedReply\": \"I haven\'t verified an order yet. Please repeat the exact seven-digit order ID slowly, one digit at a time, or share the ten-digit mobile number registered with the order.\"}}, {\"x\": 1340, \"y\": 40, \"id\": \"n_api_lookup2\", \"kind\": \"api\", \"label\": \"Order Lookup API (retry)\", \"config\": {\"connection\": \"Honasa Order Lookup\"}}, {\"x\": 40, \"y\": 170, \"id\": \"n_msg_cant_locate\", \"kind\": \"message\", \"label\": \"Lookup failed\", \"config\": {\"text\": \"I\'m still unable to locate this order in our system.\"}}, {\"x\": 300, \"y\": 170, \"id\": \"n_intent_agent_lookup\", \"kind\": \"intent\", \"label\": \"Offer agent (lookup failed)\", \"config\": {\"prompt\": \"Would you like me to connect you to a support executive who can help find your order?\", \"unmatchedReply\": \"I still haven\'t verified an order. Please share the exact seven-digit order ID or the ten-digit registered mobile number, or clearly say that you want a support executive.\", \"identifierCorrection\": {\"target\": \"n_api_lookup2\", \"pattern\": \"(?<![0-9])([0-9]{10}|[0-9]{7})(?![0-9])\", \"variable\": \"order_ref2\", \"entityType\": \"text\"}}}, {\"x\": 560, \"y\": 170, \"id\": \"n_hub\", \"kind\": \"intent\", \"label\": \"What do you need?\", \"config\": {\"prompt\": \"I\'ve found your order. Would you like the order status and delivery details, or help with a return or replacement?\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"The caller\'s order was just found and its verified facts are loaded. Briefly confirm the order was found — you may name the product from the verified order facts — then ask exactly what they need: the order status and delivery details, or help with a return or replacement. Never pick an option for them.\"}}, {\"x\": 820, \"y\": 170, \"id\": \"n_msg_order_answer\", \"kind\": \"message\", \"label\": \"Answer from order facts\", \"config\": {\"text\": \"I have your order details here — please tell me which detail you need: the status, delivery, amount, or refund.\", \"respondFromContext\": true}}, {\"x\": 1080, \"y\": 170, \"id\": \"n_api_tracklink\", \"kind\": \"api\", \"label\": \"Send Tracking Link API\", \"config\": {\"connection\": \"Honasa Send Tracking Link\"}}, {\"x\": 1340, \"y\": 170, \"id\": \"n_msg_tracklink_ok\", \"kind\": \"message\", \"label\": \"Tracking link sent\", \"config\": {\"text\": \"Done — I\'ve sent the tracking link on WhatsApp to your registered number. You can tap it anytime to see the live status.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"Confirm the tracking link was just sent successfully on WhatsApp to the caller\'s registered mobile number — the send is system-verified. Do not promise anything else.\"}}, {\"x\": 40, \"y\": 300, \"id\": \"n_msg_tracklink_fail\", \"kind\": \"message\", \"label\": \"Tracking not live\", \"config\": {\"text\": \"I\'m sorry — live tracking isn\'t available for this order yet. It becomes active once the order is shipped.\"}}, {\"x\": 300, \"y\": 300, \"id\": \"n_intent_reason\", \"kind\": \"intent\", \"label\": \"What\'s the issue?\", \"config\": {\"prompt\": \"Sure, I can help with that. Could you tell me what the issue is — is the product damaged, wrong or missing, is it defective or expired, or do you simply no longer need it?\"}}, {\"x\": 560, \"y\": 300, \"id\": \"n_cond_eligible\", \"kind\": \"condition\", \"label\": \"Return eligible?\", \"config\": {\"value\": \"true\", \"operator\": \"equals\", \"variable\": \"return_eligible\"}}, {\"x\": 820, \"y\": 300, \"id\": \"n_intent_ret_confirm\", \"kind\": \"intent\", \"label\": \"Confirm return\", \"config\": {\"prompt\": \"Good news — this order is eligible for return. Shall I raise the return request now?\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"Tell the caller this order is eligible for return under the seven-day return policy — the eligibility is system-verified — and ask exactly whether you should raise the return request now.\"}}, {\"x\": 1080, \"y\": 300, \"id\": \"n_api_ret_com\", \"kind\": \"api\", \"label\": \"Return Request API\", \"config\": {\"connection\": \"Honasa Return Request\"}}, {\"x\": 1340, \"y\": 300, \"id\": \"n_msg_return_ok\", \"kind\": \"message\", \"label\": \"Return raised\", \"config\": {\"text\": \"Done — I\'ve raised your return request. The return link will be shared over WhatsApp on your registered number; please complete the return by following that link.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"Confirm the return request was just raised successfully — it is system-verified — and that the return link is being shared over WhatsApp on the caller\'s registered number, where they can complete the return by following the link.\"}}, {\"x\": 40, \"y\": 430, \"id\": \"n_msg_ret_declined\", \"kind\": \"message\", \"label\": \"Return declined\", \"config\": {\"text\": \"No problem — I won\'t raise a return for this order.\"}}, {\"x\": 300, \"y\": 430, \"id\": \"n_msg_ret_ineligible\", \"kind\": \"message\", \"label\": \"Return not eligible\", \"config\": {\"text\": \"I\'m sorry — this order isn\'t eligible for a return under the return policy, which allows returns within seven days of delivery for eligible products.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"Explain politely, using only the verified facts, why this order is not eligible for a return — the seven-day return window has closed, the item category is not returnable, or the order has not been delivered yet. Mention the seven-day policy briefly. Never offer an exception or promise a refund.\"}}, {\"x\": 560, \"y\": 430, \"id\": \"n_intent_agent_offer\", \"kind\": \"intent\", \"label\": \"Offer agent\", \"config\": {\"prompt\": \"Would you like me to connect you to a support executive about this?\"}}, {\"x\": 820, \"y\": 430, \"id\": \"n_msg_okay_more\", \"kind\": \"message\", \"label\": \"Acknowledged\", \"config\": {\"text\": \"Alright.\"}}, {\"x\": 1080, \"y\": 430, \"id\": \"n_ask_dmg\", \"kind\": \"ask\", \"label\": \"Damage details\", \"config\": {\"question\": \"I\'m really sorry about that. Could you tell me which product was damaged and what the damage looks like?\", \"variable\": \"damage_details\", \"entityType\": \"text\"}}, {\"x\": 1340, \"y\": 430, \"id\": \"n_intent_dmg_choice\", \"kind\": \"intent\", \"label\": \"Damaged: replace or refund?\", \"config\": {\"prompt\": \"Thank you for the details. Would you prefer a replacement, or would you like to return it for a refund?\"}}, {\"x\": 40, \"y\": 560, \"id\": \"n_api_dmg_rep\", \"kind\": \"api\", \"label\": \"Damaged Replacement API\", \"config\": {\"connection\": \"Honasa Damaged Replacement\"}}, {\"x\": 300, \"y\": 560, \"id\": \"n_api_dmg_ret\", \"kind\": \"api\", \"label\": \"Damaged Return API\", \"config\": {\"connection\": \"Honasa Damaged Return\"}}, {\"x\": 560, \"y\": 560, \"id\": \"n_ask_wrong\", \"kind\": \"ask\", \"label\": \"Wrong item details\", \"config\": {\"question\": \"I apologize for the inconvenience. Could you tell me what you received, and what you had actually ordered?\", \"variable\": \"wrong_details\", \"entityType\": \"text\"}}, {\"x\": 820, \"y\": 560, \"id\": \"n_intent_wrong_choice\", \"kind\": \"intent\", \"label\": \"Wrong: replace or refund?\", \"config\": {\"prompt\": \"Thanks for confirming. Would you like the correct product as a replacement, or would you prefer to 