lse\"}, {\"id\": \"e_ptype_ok\", \"to\": \"n_mop\", \"from\": \"n_ptype\", \"label\": \"next\"}, {\"id\": \"e_ptype_fb\", \"to\": \"n_agent\", \"from\": \"n_ptype\", \"label\": \"fallback\"}, {\"id\": \"e_mop_ok\", \"to\": \"n_guide\", \"from\": \"n_mop\", \"label\": \"next\"}, {\"id\": \"e_mop_fb\", \"to\": \"n_agent\", \"from\": \"n_mop\", \"label\": \"fallback\"}, {\"id\": \"e_guide\", \"to\": \"n_close\", \"from\": \"n_guide\"}]','[]','2026-07-27 17:31:29','2026-07-27 17:31:31','usr_48f09517dcda','usr_48f09517dcda',0,NULL,NULL),('wf_dfa638b8dcc4','tn_04250683f1b3','bot_75ce66eb9e63','Zepto raincoat t-shirt bag deduction journey',2,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 300, \"y\": 40, \"id\": \"n_ask_u_deduction_amount\", \"kind\": \"ask\", \"label\": \"Ask — u_deduction_amount\", \"config\": {\"question\": \"सबसे पहले — आपका deduction amount कितना था?\", \"variable\": \"u_deduction_amount\", \"entityType\": \"text\"}}, {\"x\": 560, \"y\": 40, \"id\": \"n_ask_u_deduction_count\", \"kind\": \"ask\", \"label\": \"Ask — u_deduction_count\", \"config\": {\"question\": \"यह deduction कितनी बार हुआ है?\", \"variable\": \"u_deduction_count\", \"entityType\": \"text\"}}, {\"x\": 820, \"y\": 40, \"id\": \"n_ask_u_items_received\", \"kind\": \"ask\", \"label\": \"Ask — u_items_received\", \"config\": {\"question\": \"क्या आपको Bag, T-shirt और Raincoat मिले थे — yes या no?\", \"variable\": \"u_items_received\", \"entityType\": \"text\"}}, {\"x\": 1080, \"y\": 40, \"id\": \"n_ask_u_deduction_date\", \"kind\": \"ask\", \"label\": \"Ask — u_deduction_date\", \"config\": {\"question\": \"यह deduction किस date या week में हुआ था?\", \"variable\": \"u_deduction_date\", \"entityType\": \"text\"}}, {\"x\": 40, \"y\": 170, \"id\": \"n_api\", \"kind\": \"api\", \"label\": \"Register concern\", \"config\": {\"text\": \"धन्यवाद। एक moment दीजिए — मैं आपकी concern support team में register कर रही हूँ।\", \"connection\": \"Zepto Register Uniform Deduction Concern\"}}, {\"x\": 300, \"y\": 170, \"id\": \"n_confirmed\", \"kind\": \"message\", \"label\": \"Registered (grounded)\", \"config\": {\"text\": \"सारी जानकारी देने के लिए धन्यवाद। आपकी concern register हो गई है, और हमारी support team जल्द ही आपसे connect करेगी।\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"The concern ticket was just registered successfully — the ticket facts (ticket reference, concern name, callback expectation) are in this conversation\'s system results. In the caller\'s language (default: natural Hinglish — Hindi in Devanagari with everyday English terms), thank the partner for providing all the information, tell them their concern has been registered, state the ticket reference exactly as given, and assure them the support team will connect with them within the stated callback window. Never invent any detail.\"}}, {\"x\": 560, \"y\": 170, \"id\": \"n_pending\", \"kind\": \"message\", \"label\": \"Script closing (API unavailable)\", \"config\": {\"text\": \"सारी जानकारी देने के लिए धन्यवाद। Rest assured — हमारी team जल्द ही आपसे connect करेगी।\"}}, {\"x\": 820, \"y\": 170, \"id\": \"n_hub_more\", \"kind\": \"intent\", \"label\": \"Anything else?\", \"config\": {\"prompt\": \"क्या मैं आपकी किसी और चीज़ में help कर सकती हूँ?\", \"unmatchedReply\": \"अगर इसी concern से जुड़ा कोई और सवाल है तो बताइए। कोई दूसरा concern है तो मैं support executive से connect कर सकती हूँ — या \'नहीं\' बोलिए और मैं call close कर दूँ।\"}}, {\"x\": 1080, \"y\": 170, \"id\": \"n_msg_close\", \"kind\": \"message\", \"label\": \"Scripted closing\", \"config\": {\"text\": \"Zepto Support को contact करने के लिए धन्यवाद! आपका दिन शुभ हो!\"}}, {\"x\": 40, \"y\": 300, \"id\": \"n_handover\", \"kind\": \"handover\", \"label\": \"Support executive handover\", \"config\": {\"text\": \"ठीक है — मैं आपकी बात हमारे support executive से करा रही हूँ। कृपया line पर बने रहिए।\", \"queue\": \"partner_support\"}}, {\"x\": 300, \"y\": 300, \"id\": \"n_end\", \"kind\": \"end\", \"label\": \"Call ends\"}]','[{\"id\": \"e_n_start__n_ask_u_deduction_amount\", \"to\": \"n_ask_u_deduction_amount\", \"from\": \"n_start\"}, {\"id\": \"e_n_ask_u_deduction_amount__n_ask_u_deduction_count\", \"to\": \"n_ask_u_deduction_count\", \"from\": \"n_ask_u_deduction_amount\"}, {\"id\": \"e_n_ask_u_deduction_count__n_ask_u_items_received\", \"to\": \"n_ask_u_items_received\", \"from\": \"n_ask_u_deduction_count\"}, {\"id\": \"e_n_ask_u_items_received__n_ask_u_deduction_date\", \"to\": \"n_ask_u_deduction_date\", \"from\": \"n_ask_u_items_received\"}, {\"id\": \"e_n_ask_u_deduction_date__n_api\", \"to\": \"n_api\", \"from\": \"n_ask_u_deduction_date\"}, {\"id\": \"e_n_api__n_confirmed__1990\", \"to\": \"n_confirmed\", \"from\": \"n_api\", \"label\": \"success\"}, {\"id\": \"e_n_api__n_pending__8902\", \"to\": \"n_pending\", \"from\": \"n_api\", \"label\": \"failure\"}, {\"id\": \"e_n_confirmed__n_hub_more\", \"to\": \"n_hub_more\", \"from\": \"n_confirmed\"}, {\"id\": \"e_n_pending__n_hub_more\", \"to\": \"n_hub_more\", \"from\": \"n_pending\"}, {\"id\": \"e_n_hub_more__n_handover__4612\", \"to\": \"n_handover\", \"from\": \"n_hub_more\", \"label\": \"another issue/one more issue/ek aur issue/aur ek issue/doosra issue/dusra issue/aur bhi issue/dusri concern/एक और इशू/और एक इशू/दूसरा इशू/और भी इशू/दूसरी कंसर्न\"}, {\"id\": \"e_n_hub_more__n_handover__6244\", \"to\": \"n_handover\", \"from\": \"n_hub_more\", \"label\": \"agent/human/executive/supervisor/manager/support executive/customer care/insaan se/aadmi se/kisi se baat karao/एजेंट/सुपरवाइज़र/मैनेजर/इंसान से/आदमी से/किसी से बात कराओ\"}, {\"id\": \"e_n_hub_more__n_msg_close__7077\", \"to\": \"n_msg_close\", \"from\": \"n_hub_more\", \"label\": \"no/nothing/nahi/bas/bas itna hi/that\'s all/thats all/thank you/thanks/theek hai bas/nothing else/ho gaya/nahi bas/नहीं/बस/बस इतना ही/धन्यवाद/शुक्रिया/ठीक है बस/हो गया\"}, {\"id\": \"e_n_msg_close__n_end\", \"to\": \"n_end\", \"from\": \"n_msg_close\"}]','[]','2026-08-31 18:46:25','2026-08-31 18:46:26','usr_9b626787e757','usr_9b626787e757',0,NULL,NULL),('wf_e68576dad54d','tn_fdf9813f16cf','bot_7409b658b502','Collections plan',2,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\", \"config\": {\"text\": \"I can set up a payment plan for you.\"}}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"ask\", \"label\": \"Ask amount\", \"config\": {\"question\": \"How much can you pay per month?\", \"variable\": \"amount\", \"entityType\": \"number\"}}, {\"x\": 260, \"y\": 260, \"id\": \"n4\", \"kind\": \"condition\", \"label\": \"Check amount\", \"config\": {\"value\": 1000, \"operator\": \"gte\", \"variable\": \"amount\"}}, {\"x\": 480, \"y\": 200, \"id\": \"n5\", \"kind\": \"end\", \"label\": \"End call\", \"config\": {\"text\": \"Your plan is registered. Goodbye!\"}}, {\"x\": 480, \"y\": 330, \"id\": \"n6\", \"kind\": \"handover\", \"label\": \"Agent\", \"config\": {\"text\": \"An agent needs to approve that amount.\"}}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}, {\"id\": \"e3\", \"to\": \"n4\", \"from\": \"n3\"}, {\"id\": \"e4\", \"to\": \"n5\", \"from\": \"n4\", \"label\": \"true\"}, {\"id\": \"e5\", \"to\": \"n6\", \"from\": \"n4\", \"label\": \"false\"}]','[]','2026-08-18 17:24:33','2026-08-18 17:24:33','usr_da0953b39213','usr_da0953b39213',0,NULL,NULL),('wf_e732516cdae2','tn_de5cc992b1e9','bot_aa486f4b7b8e','Billing support journey',1,'draft','[{\"x\": 40, \"y\": 40, \"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"x\": 40, \"y\": 150, \"id\": \"n2\", \"kind\": \"message\", \"label\": \"Greeting\"}, {\"x\": 40, \"y\": 260, \"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-08-18 13:50:36','2026-08-18 13:50:36','usr_180893eb0b1b',NULL,0,NULL,NULL),('wf_e8cf9421743e','tn_0b3837e6bb5a','bot_73eeb5185d1f','FAQ & information journey',4,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Call starts\", \"config\": {}}, {\"x\": 300, \"y\": 40, \"id\": \"n_verify\", \"kind\": \"intent\", \"label\": \"Verify customer\", \"config\": {\"prompt\": \"Sorry, just to confirm, am I speaking with {customer_name}?\", \"unmatchedReply\": \"Sorry, could you please confirm once — am I speaking with {customer_name}?\"}}, {\"x\": 40, \"y\": 170, \"id\": \"n_msg_wrong\", \"kind\": \"message\", \"label\": \"Wrong party close\", \"config\": {\"text\": \"Apologies for the inconvenience — I won\'t share any account details on this line. Thank you, have a good day.\"}}, {\"x\": 560, \"y\": 170, \"id\": \"n_purpose\", \"kind\": \"message\", \"label\": \"Call purpose + progress readback\", \"config\": {\"text\": \"Thank you for confirming. Ye call aapke Kotak NEO investment journey ke baare mein hai. Aapka account opening process abhi complete nahi hua hai — main aapko baaki ke steps complete karne mein madad kar sakti hoon.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"Open by thanking them for confirming, then state in two or three short sentences that this call is about the Kotak NEO investment journey they started, and read their progress back to them. Caller context carries \'onboarding_stage_completed_label\' (the last step they finished), \'onboarding_stage_pending_label\' (the very next step to do), \'onboarding_steps_done\' and \'onboarding_steps_total\'. Speak the step NAMES, not a bare count — say that the record shows they have completed up to the completed step, that the pending step is what comes next, and you may mention how many of the total steps are done. Then offer to help them finish the remaining steps, and stop. WHEN \'onboarding_stage_completed_label\' IS NULL, EMPTY OR MISSING, say only that the onboarding has not started yet and the first step is the pending one. WHEN \'onboarding_stage_pending_label\' IS NULL, EMPTY OR MISSING, do not name any step and do not quote any count — just say the onboarding is still pending and offer to help. Never invent a step name or a number, never say \'step two of four\' or any count that is not in the context, and never claim the account is open or approved.\"}}, {\"x\": 820, \"y\": 170, \"id\": \"n_offer_help\", \"kind\": \"intent\", \"label\": \"Start / resume onboarding?\", \"config\": {\"prompt\": \"To kya hum abhi ye step saath mein complete kar lein?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bata dijiye — hum abhi ye step complete kar lein, ya aapko kuch aur puchna hai?\", \"captureVariable\": \"onboarding_stage\", \"responseDirective\": \"You have just read their progress back. Ask ONCE, in one short sentence, whether you should walk them through the pending step right now. Do not repeat the step names you just said, do not list the remaining steps, and do not start explaining any step here — the flow does that next. If the customer has already named a step they are stuck on, do not ask this at all; simply acknowledge it in a few words.\"}}, {\"x\": 560, \"y\": 300, \"id\": \"n_router\", \"kind\": \"intent\", \"label\": \"Intent router\", \"config\": {\"prompt\": \"Aap batayein, main aapki kis tarah help kar sakti hoon — account opening, F&O activation, Refer & Earn, ya koi aur query?\", \"unmatchedReply\": \"Maaf kijiye, main samajh nahi paaya. Kya aap thoda aur detail mein bata sakte hain — account opening, F&O, charges, ya kuch aur?\"}}, {\"x\": 40, \"y\": 430, \"id\": \"n_account_setup\", \"kind\": \"message\", \"label\": \"Account setup\", \"config\": {\"text\": \"Stocks mein invest karne ke liye ek Demat aur Trading account chahiye hota hai. Ek baar active hone ke baad aap stocks, IPO, commodities, mutual funds aur ETF — sab ek hi platform par access kar sakte hain. Main aapko remaining onboarding steps mein help kar sakti hoon.\"}}, {\"x\": 300, \"y\": 430, \"id\": \"n_fno_check\", \"kind\": \"intent\", \"label\": \"F&O document check\", \"config\": {\"prompt\": \"F&O activation ke liye financial proof chahiye. Kya inmein se koi document abhi aapke paas available hai — bank statement, salary slip, ITR, Form 16, DP statement ya net-worth certificate?\", \"unmatchedReply\": \"Bas itna bataiye — in dastavezon mein se koi ek abhi aapke paas available hai, haan ya nahi?\"}}, {\"x\": 300, \"y\": 560, \"id\": \"n_fno_yes\", \"kind\": \"message\", \"label\": \"F&O — has document\", \"config\": {\"text\": \"Bahut badhiya. Account open hone ke baad, aap Kotak NEO App mein Service Request se Segment Activation option mein jaakar ye document upload kar sakte hain.\"}}, {\"x\": 560, \"y\": 560, \"id\": \"n_fno_no\", \"kind\": \"message\", \"label\": \"F&O — no document\", \"config\": {\"text\": \"Koi baat nahi, aap abhi bhi account open kar sakte hain. Demat account mein 10,000 rupaye ki equity shares 2-3 working days tak hold karne par F&O automatically activate ho jaata hai. Document baad mein bhi Service Request se upload kiya ja sakta hai.\"}}, {\"x\": 560, \"y\": 430, \"id\": \"n_refer\", \"kind\": \"message\", \"label\": \"Refer & Earn\", \"config\": {\"text\": \"Refer & Earn mein, jab aapka refer kiya hua person referral link se 30 din ke andar account open karta hai, aapko 300 rupaye cash bonus milta hai — ek mahine mein pehle 4 successful referrals tak. Iske alawa, agle 2 saal tak unke brokerage charges ka 15% bhi har mahine ki 20 tareekh tak aapko credit hota hai.\"}}, {\"x\": 820, \"y\": 430, \"id\": \"n_etf\", \"kind\": \"message\", \"label\": \"ETF explainer\", \"config\": {\"text\": \"ETF ko simple language mein shares ki ek basket samajh sakte hain. For example, Nifty ETF ke through investment multiple companies mein spread ho sakta hai, instead of depending on just one company.\"}}, {\"x\": 1080, \"y\": 430, \"id\": \"n_faq\", \"kind\": \"knowledge\", \"label\": \"General FAQ (KB)\", \"config\": {\"fallbackText\": \"Iski exact jaankari main abhi confirm nahi kar sakta — main aapko support team se connect kar deta hoon.\", \"planResolutionNote\": \"Before quoting brokerage, AMC, or MTF interest, resolve the customer\'s plan from backend data — figures differ across Youth/Trade Free/Pro/Premium plans.\"}}, {\"x\": 1340, \"y\": 430, \"id\": \"n_objection\", \"kind\": \"intent\", \"label\": \"Objection — identify concern\", \"config\": {\"prompt\": \"Main samajh sakti hoon. Kya wajah hai — charges zyada lagte hain, pehle se kisi aur broker ka account hai, abhi interested nahi hain, ya time nahi hai?\", \"unmatchedReply\": \"Koi baat nahi, bas itna bata dijiye — concern charges ko lekar hai ya kuch aur?\"}}, {\"x\": 1340, \"y\": 560, \"id\": \"n_obj_charges\", \"kind\": \"message\", \"label\": \"Objection — charges response\", \"config\": {\"text\": \"Kotak NEO par brokerage kaafi competitive hai — Equity Intraday aur F&O par max 10 rupaye per order tak ka charge lagta hai, plan ke hisaab se. Kya main aapko current plans ke baare mein bata sakti hoon?\"}}, {\"x\": 1600, \"y\": 560, \"id\": \"n_obj_general\", \"kind\": \"message\", \"label\": \"Objection — general respectful response\", \"config\": {\"text\": \"Bilkul samajh sakti hoon, koi zabardasti nahi hai. Bas agar future mein zaroorat pade to Kotak NEO available hai. Kya aap chahenge main aapko kuch aur jaankari doon?\"}}, {\"x\": 1470, \"y\": 690, \"id\": \"n_obj_followup\", \"kind\": \"intent\", \"label\": \"Continue or close?\", \"config\": {\"prompt\": \"Kya aap kuch aur jaanna chahenge, ya call yahin close kar dein?\", \"unmatchedReply\": \"Bas itna bata dijiye — kuch aur puchna hai, ya call close kar dein?\"}}, {\"x\": 1600, \"y\": 430, \"id\": \"n_handover\", \"kind\": \"handover\", \"label\": \"Connect to agent\", \"config\": {\"text\": \"Theek hai, main aapko humari support team se connect kar rahi hoon — kripya line par bane rahiye.\", \"preserve\": [\"customer_id\", \"customer_name\", \"current_intent\", \"previous_intent\", \"onboarding_stage\", \"onboarding_stage_pending\", \"conversation_summary\", \"handoff_reason\"]}}, {\"x\": 1470, \"y\": 820, \"id\": \"n_close\", \"kind\": \"message\", \"label\": \"Closing\", \"config\": {\"text\": \"Thank you for your valuable time. Have a great day.\"}}, {\"x\": 1470, \"y\": 950, \"id\": \"n_end\", \"kind\": \"end\", \"label\": \"End call\", \"config\": {}}, {\"x\": 40, \"y\": 1600, \"id\": \"n_cond_pan\", \"kind\": \"condition\", \"label\": \"Pending = PAN?\", \"config\": {\"value\": \"pan\", \"operator\": \"equals\", \"variable\": \"onboarding_stage_pending\"}}, {\"x\": 300, \"y\": 1600, \"id\": \"n_cond_digilocker\", \"kind\": \"condition\", \"label\": \"Pending = DigiLocker?\", \"config\": {\"value\": \"digilocker\", \"operator\": \"equals\", \"variable\": \"onboarding_stage_pending\"}}, {\"x\": 560, \"y\": 1600, \"id\": \"n_cond_bank\", \"kind\": \"condition\", \"label\": \"Pending = bank?\", \"config\": {\"value\": \"bank\", \"operator\": \"equals\", \"variable\": \"onboarding_stage_pending\"}}, {\"x\": 820, \"y\": 1600, \"id\": \"n_cond_nominee\", \"kind\": \"condition\", \"label\": \"Pending = nominee?\", \"config\": {\"value\": \"nominee\", \"operator\": \"equals\", \"variable\": \"onboarding_stage_pending\"}}, {\"x\": 1080, \"y\": 1600, \"id\": \"n_cond_selfie\", \"kind\": \"condition\", \"label\": \"Pending = selfie?\", \"config\": {\"value\": \"selfie\", \"operator\": \"equals\", \"variable\": \"onboarding_stage_pending\"}}, {\"x\": 1340, \"y\": 1600, \"id\": \"n_cond_sign\", \"kind\": \"condition\", \"label\": \"Pending = signature?\", \"config\": {\"value\": \"sign\", \"operator\": \"equals\", \"variable\": \"onboarding_stage_pending\"}}, {\"x\": 1600, \"y\": 1600, \"id\": \"n_cond_esign\", \"kind\": \"condition\", \"label\": \"Pending = eSign?\", \"config\": {\"value\": \"esign\", \"operator\": \"equals\", \"variable\": \"onboarding_stage_pending\"}}, {\"x\": 560, \"y\": 1080, \"id\": \"n_onboard_stage\", \"kind\": \"intent\", \"label\": \"Onboarding — ask which step (no record)\", \"config\": {\"prompt\": \"Aap onboarding mein kis step par ruke hain — PAN, Aadhaar DigiLocker, bank details, nominee, selfie, signature, ya eSign?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Koi baat nahi — bas itna bata dijiye, aap PAN wale step par atke hain, Aadhaar par, bank par, ya selfie, signature ya eSign par?\", \"captureVariable\": \"onboarding_stage\", \"responseDirective\": \"You reach this only when the record does not tell you which step is pending, or the customer says they are on a different step than the record showed. Ask ONCE which step they are on, naming the app\'s steps in their own order — PAN, Aadhaar DigiLocker, bank details, nominee, selfie, signature, eSign — as one short spoken list, never as a numbered read-out. Never mention that the record is missing or wrong, and never invent a step name or number. If they only say the OTP is not arriving, do not guess: ask whether that OTP is for the Aadhaar DigiLocker step or for the final eSign step. Never explain any step\'s guidance in this turn — that comes only after they name the step.\"}}, {\"x\": 40, \"y\": 1210, \"id\": \"n_stage_pan\", \"kind\": \"message\", \"label\": \"Step 1 — PAN card\", \"config\": {\"text\": \"Theek hai, PAN wale step se shuru karte hain. PAN card ki details dhyan se enter kijiye, khaas taur par date of birth. Agar date ya month single digit hai to uske aage zero lagaiye — jaise 5 ki jagah 05 — aur phir Continue par click kar dijiye.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"You are walking the customer through the PAN step — this is step one of seven. They have either resumed here or just finished nothing before it. Name the step in a few words, then give the guidance like a helpful rep on the phone, in the customer\'s own language, in two or three short sentences total. The facts you may give, and nothing beyond them: check the PAN card details and enter them again; enter the date of birth correctly; if a date or month is a single digit, put a zero in front of it before entering; then tap Continue. Speak the zero example out loud naturally, for example five becoming zero-five. Do not add any other PAN troubleshooting, do not mention re-KYC, name correction, the income-tax portal or any website, and do not ask a question — the flow asks the next one.\"}}, {\"x\": 40, \"y\": 1340, \"id\": \"n_chk_pan\", \"kind\": \"intent\", \"label\": \"PAN — done?\", \"config\": {\"prompt\": \"Ho gaya? PAN wala step complete ho gaya?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — PAN step ho gaya, ya abhi bhi error aa raha hai?\", \"responseDirective\": \"Ask only whether the PAN step went through. One short question, in the customer\'s language. Do not repeat the instructions you just gave and do not add any new fact.\"}}, {\"x\": 300, \"y\": 1210, \"id\": \"n_stage_digilocker\", \"kind\": \"message\", \"label\": \"Step 2 — Aadhaar DigiLocker\", \"config\": {\"text\": \"Badhiya. Ab agla step hai Aadhaar DigiLocker. Isme Aadhaar number sahi-sahi, dhyan se enter kijiye. OTP usi mobile number par aayega jo aapke Aadhaar se linked hai — kya wo number abhi aapke paas available hai?\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"You are walking the customer to the Aadhaar DigiLocker step — step two of seven. If they have just cleared the previous step, acknowledge it in two or three words and name this next step before the guidance; if they resumed straight here, just name the step. The facts you may give, and nothing beyond them: enter the Aadhaar number correctly; the OTP goes to the mobile number linked to the Aadhaar; and the Aadhaar must also be linked with the PAN. Close by asking them to confirm that the Aadhaar-linked mobile number is with them right now — that is the ONE question in this turn. Never explain how to link a mobile number to an Aadhaar or a PAN to an Aadhaar, never name UIDAI or any website or centre, never quote a timeline or a fee, and never ask the customer to speak their Aadhaar number on this call.\"}}, {\"x\": 300, \"y\": 1340, \"id\": \"n_chk_digilocker\", \"kind\": \"intent\", \"label\": \"DigiLocker — done?\", \"config\": {\"prompt\": \"DigiLocker se Aadhaar verify ho gaya?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — Aadhaar verify ho gaya, ya abhi bhi atka hua hai?\", \"responseDirective\": \"Ask only whether the Aadhaar DigiLocker verification went through. One short question, in the customer\'s language, with no repetition and no new facts.\"}}, {\"x\": 560, \"y\": 1210, \"id\": \"n_stage_bank\", \"kind\": \"message\", \"label\": \"Step 3 — bank details\", \"config\": {\"text\": \"Badhiya. Ab bank details wala step hai. Pehle ye confirm kar lijiye ki aapka bank account active hai. Agar UPI se bank link nahi ho raha, to bank ka naam manually search kijiye aur required bank details khud enter kar dijiye — us tarah se bhi ho jaata hai.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"You are walking the customer to the bank details step — step three of seven. If they have just cleared the previous step, acknowledge it in two or three words and name this next step before the guidance; if they resumed straight here, just name the step. The facts you may give, and nothing beyond them: first confirm the bank account is active; and if the account will not link through UPI, search the bank name manually and enter the required bank details by hand instead. Keep it to two or three short sentences in the customer\'s language. Do not name any bank, do not quote a penny-drop amount, a verification timeline or any charge, and never ask the customer to say an account number, IFSC, UPI PIN, card number or any other banking credential on this call.\"}}, {\"x\": 560, \"y\": 1340, \"id\": \"n_chk_bank\", \"kind\": \"intent\", \"label\": \"Bank — done?\", \"config\": {\"prompt\": \"Bank account add ho gaya?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — bank account add ho gaya, ya abhi bhi error aa raha hai?\", \"responseDirective\": \"Ask only whether the bank account got added. One short question, in the customer\'s language, with no repetition and no new facts. Never ask for the account details themselves.\"}}, {\"x\": 820, \"y\": 1210, \"id\": \"n_stage_nominee\", \"kind\": \"message\", \"label\": \"Step 4 — nominee\", \"config\": {\"text\": \"Badhiya. Ab nominee wala step hai. Agar nominee ki details abhi aapke paas nahi hain to koi dikkat nahi — ye step aap filhaal skip kar sakte hain, nominee baad mein, account khulne ke baad bhi add kiya ja sakta hai.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"You are walking the customer to the nominee step — step four of seven. If they have just cleared the previous step, acknowledge it in two or three words and name this next step before the guidance; if they resumed straight here, just name the step. The facts you may give, and nothing beyond them: if the nominee details are not with them right now, this step can be skipped, and a nominee can be added later, even after the account is opened. One or two short sentences in the customer\'s language. Do not state how many nominees are allowed, any share or percentage split rule, any deadline, any document needed, or any consequence of skipping — none of that is approved. Do not ask a question here.\"}}, {\"x\": 820, \"y\": 1340, \"id\": \"n_chk_nominee\", \"kind\": \"intent\", \"label\": \"Nominee — done or skipped?\", \"config\": {\"prompt\": \"Ho gaya? Hum agle step par badh sakte hain?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — nominee add kar diya ya skip kar diya, hum aage badh sakte hain?\", \"responseDirective\": \"Ask only whether the nominee step is done or skipped so you can move on. One short question, in the customer\'s language, with no repetition and no new facts.\"}}, {\"x\": 1080, \"y\": 1210, \"id\": \"n_stage_selfie\", \"kind\": \"message\", \"label\": \"Step 5 — selfie\", \"config\": {\"text\": \"Badhiya. Ab selfie wala step hai. Apna chehra circle ke bilkul beech mein rakhiye, aur jaise hi circle green ho jaaye, selfie capture kar lijiye. Agar cap ya headphones pehne hain to unhe pehle utaar dijiye.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"You are walking the customer to the selfie step — step five of seven. If they have just cleared the previous step, acknowledge it in two or three words and name this next step before the guidance; if they resumed straight here, just name the step. The facts you may give, and nothing beyond them: position the face at the centre of the circle; capture the selfie once the circle turns green; and remove a cap or headphones before capturing. Two or three short sentences in the customer\'s language, spoken as guidance rather than a checklist. Do not add advice about lighting, background, spectacles, camera permission or network — none of it is approved. Do not ask a question here.\"}}, {\"x\": 1080, \"y\": 1340, \"id\": \"n_chk_selfie\", \"kind\": \"intent\", \"label\": \"Selfie — done?\", \"config\": {\"prompt\": \"Selfie capture ho gayi?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — selfie capture ho gayi, ya abhi bhi nahi ho rahi?\", \"responseDirective\": \"Ask only whether the selfie got captured. One short question, in the customer\'s language, with no repetition and no new facts.\"}}, {\"x\": 1340, \"y\": 1210, \"id\": \"n_stage_sign\", \"kind\": \"message\", \"label\": \"Step 6 — signature\", \"config\": {\"text\": \"Badhiya. Ab signature wala step hai. Signature bilkul waisa hi kijiye jaisa aapke PAN card par hai, aur dhyan rakhiye ki wo box ke beech mein hi rahe, kinare se bahar na jaaye.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"You are walking the customer to the signature step — step six of seven. If they have just cleared the previous step, acknowledge it in two or three words and name this next step before the guidance; if they resumed straight here, just name the step. The facts you may give, and nothing beyond them: sign exactly as the signature appears on the PAN card, and place the signature properly within the centre of the box. Two short sentences in the customer\'s language. Do not suggest a stylus, a scanned or uploaded signature, a different device, or any other method — none of it is approved. Do not ask a question here.\"}}, {\"x\": 1340, \"y\": 1340, \"id\": \"n_chk_sign\", \"kind\": \"intent\", \"label\": \"Signature — done?\", \"config\": {\"prompt\": \"Signature ho gaya?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — signature accept ho gaya, ya dobara karna pad raha hai?\", \"responseDirective\": \"Ask only whether the signature went through. One short question, in the customer\'s language, with no repetition and no new facts.\"}}, {\"x\": 1600, \"y\": 1210, \"id\": \"n_stage_esign\", \"kind\": \"message\", \"label\": \"Step 7 — eSign (first attempt)\", \"config\": {\"text\": \"Badhiya, ab last step — eSign. Aadhaar number enter karke Send OTP par click kijiye. OTP usi number par aayega jo aapke Aadhaar se registered hai — kya wo number abhi aapke paas hai?\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"You are walking the customer to the eSign step — step seven, the LAST step. If they have just cleared the previous step, acknowledge it in two or three words and say this is the final step; if they resumed straight here, just name the step. This turn covers only the FIRST attempt. The facts you may give, and nothing beyond them: enter the Aadhaar number and tap Send OTP; the OTP goes to the mobile number registered with the Aadhaar. Close by asking them to confirm that Aadhaar-linked number is with them — that is the ONE question in this turn. Do NOT mention Resend OTP, disconnecting the call, waiting, or the English option yet; the flow has separate steps for each of those. Never ask the customer to speak the Aadhaar number or the OTP aloud on this call.\"}}, {\"x\": 1600, \"y\": 1340, \"id\": \"n_chk_esign\", \"kind\": \"intent\", \"label\": \"eSign — OTP received?\", \"config\": {\"prompt\": \"OTP aa gaya?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — OTP mil gaya, ya abhi tak nahi aaya?\", \"responseDirective\": \"Ask only whether the eSign OTP has arrived. One short question, in the customer\'s language. Never ask them to read the OTP out.\"}}, {\"x\": 1860, \"y\": 1210, \"id\": \"n_stage_esign_retry\", \"kind\": \"message\", \"label\": \"eSign — OTP still not received\", \"config\": {\"text\": \"Koi baat nahi. Resend OTP par click karke thoda wait kijiye. Agar phir bhi OTP na aaye, to abhi call disconnect karke thodi der baad dobara check kar lijiye.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"The eSign OTP still has not arrived. The facts you may give, and nothing beyond them: tap Resend OTP and wait for it; and if it still does not arrive while we are on this call, disconnect and check again a little later. Say it kindly in two short sentences, in the customer\'s language. Do not blame the network or the customer, do not promise when the OTP will arrive, and do not suggest changing the Aadhaar-linked mobile number. Do not ask a question here.\"}}, {\"x\": 1860, \"y\": 1340, \"id\": \"n_chk_esign_retry\", \"kind\": \"intent\", \"label\": \"eSign — OTP received after resend?\", \"config\": {\"prompt\": \"Ab OTP aaya kya?\", \"responseMode\": \"llm_grounded\", \"unmatchedReply\": \"Bas itna bataiye — ab OTP aa gaya, ya abhi bhi nahi aaya?\", \"responseDirective\": \"Ask only whether the OTP has arrived after the resend. One short question, in the customer\'s language. Never ask them to read the OTP out.\"}}, {\"x\": 2120, \"y\": 1210, \"id\": \"n_stage_esign_finish\", \"kind\": \"message\", \"label\": \"eSign — complete it\", \"config\": {\"text\": \"Badhiya. Ab OTP daal kar English option select kijiye aur eSign process complete kar lijiye.\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"The OTP has arrived. In one or two short sentences, in the customer\'s language, tell them to enter the OTP, select the English option, and go ahead and complete the eSign. No other step and no new facts. Do not ask a question here.\"}}, {\"x\": 1080, \"y\": 1470, \"id\": \"n_onboard_done\", \"kind\": \"message\", \"label\": \"Onboarding journey complete\", \"config\": {\"text\": \"Bahut badhiya, saare steps complete ho gaye. Kya main aapki kisi aur cheez mein madad kar sakti hoon?\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"The customer has just completed eSign, the last of the seven steps, so the whole onboarding journey is done. Acknowledge that warmly in one short sentence, in their language, and ask once whether you can help with anything else. Never state when the account will be activated, never promise a timeline, and never claim the account is now open or approved — account status only ever comes from backend data.\"}}]','[{\"id\": \"e_start__verify\", \"to\": \"n_verify\", \"from\": \"n_start\"}, {\"id\": \"e_verify__purpose\", \"to\": \"n_purpose\", \"from\": \"n_verify\", \"label\": \"yes/haan/haan ji/ji haan/speaking/ye main hoon/ha bol raha hu/हाँ/जी हाँ/मैं ही बोल रहा हूँ/बोल रहा हूँ\"}, {\"id\": \"e_verify__wrong\", \"to\": \"n_msg_wrong\", \"from\": \"n_verify\", \"label\": \"no/nahi/galat number/wrong number/ye number nahi/नहीं/गलत नंबर\"}, {\"id\": \"e_wrong__end\", \"to\": \"n_end\", \"from\": \"n_msg_wrong\"}, {\"id\": \"e_purpose__offer\", \"to\": \"n_offer_help\", \"from\": \"n_purpose\"}, {\"id\": \"e_offer__resume\", \"to\": \"n_cond_pan\", \"from\": \"n_offer_help\", \"label\": \"ye