{\"x\": 1080, \"y\": 40, \"id\": \"n_ask_r_store_handover\", \"kind\": \"ask\", \"label\": \"Ask — r_store_handover\", \"config\": {\"entity\": {\"dataType\": \"text\", \"synonyms\": {\"no\": [\"no\", \"nope\", \"nahi\", \"nahin\", \"nahi diya\", \"not yet\", \"abhi nahi\", \"नहीं\", \"नहीं दिया\", \"अभी नहीं\", \"नही\"], \"yes\": [\"yes\", \"yeah\", \"yup\", \"haan\", \"haanji\", \"han ji\", \"ji haan\", \"bilkul\", \"de diya\", \"diya tha\", \"kar diya\", \"haa\", \"हाँ\", \"हां\", \"जी हाँ\", \"जी हां\", \"बिल्कुल\", \"दे दिया\", \"दिया था\", \"कर दिया\"]}, \"allowedValues\": [\"yes\", \"no\"]}, \"question\": \"क्या आपने product store team को hand over कर दिया था — yes या no?\", \"variable\": \"r_store_handover\"}}, {\"x\": 40, \"y\": 170, \"id\": \"n_cond_store_handover\", \"kind\": \"condition\", \"label\": \"Handed to store team?\", \"config\": {\"value\": \"yes\", \"operator\": \"equals\", \"variable\": \"r_store_handover\"}}, {\"x\": 300, \"y\": 170, \"id\": \"n_ask_r_store_handover_date\", \"kind\": \"ask\", \"label\": \"Ask — r_store_handover_date\", \"config\": {\"question\": \"आपने product store team को कब hand over किया था?\", \"variable\": \"r_store_handover_date\", \"entityType\": \"text\"}}, {\"x\": 560, \"y\": 170, \"id\": \"n_api\", \"kind\": \"api\", \"label\": \"Register concern\", \"config\": {\"text\": \"धन्यवाद। एक moment दीजिए — मैं आपकी concern support team में register कर रही हूँ।\", \"connection\": \"Zepto Register RTO Concern\"}}, {\"x\": 820, \"y\": 170, \"id\": \"n_confirmed\", \"kind\": \"message\", \"label\": \"Registered (grounded)\", \"config\": {\"text\": \"सारी जानकारी देने के लिए धन्यवाद। आपकी concern register हो गई है, और हमारी support team जल्द ही आपसे connect करेगी।\", \"responseMode\": \"llm_grounded\", \"responseDirective\": \"The concern ticket was just registered successfully — the ticket facts (ticket reference, concern name, callback expectation) are in this conversation\'s system results. In the caller\'s language (default: natural Hinglish — Hindi in Devanagari with everyday English terms), thank the partner for providing all the information, tell them their concern has been registered, state the ticket reference exactly as given, and assure them the support team will connect with them within the stated callback window. Never invent any detail.\"}}, {\"x\": 1080, \"y\": 170, \"id\": \"n_pending\", \"kind\": \"message\", \"label\": \"Script closing (API unavailable)\", \"config\": {\"text\": \"सारी जानकारी देने के लिए धन्यवाद। Rest assured — हमारी team जल्द ही आपसे connect करेगी।\"}}, {\"x\": 40, \"y\": 300, \"id\": \"n_hub_more\", \"kind\": \"intent\", \"label\": \"Anything else?\", \"config\": {\"prompt\": \"क्या मैं आपकी किसी और चीज़ में help कर सकती हूँ?\", \"unmatchedReply\": \"अगर इसी concern से जुड़ा कोई और सवाल है तो बताइए। कोई दूसरा concern है तो मैं support executive से connect कर सकती हूँ — या \'नहीं\' बोलिए और मैं call close कर दूँ।\"}}, {\"x\": 300, \"y\": 300, \"id\": \"n_msg_close\", \"kind\": \"message\", \"label\": \"Scripted closing\", \"config\": {\"text\": \"Zepto Support को contact करने के लिए धन्यवाद! आपका दिन शुभ हो!\"}}, {\"x\": 560, \"y\": 300, \"id\": \"n_handover\", \"kind\": \"handover\", \"label\": \"Support executive handover\", \"config\": {\"text\": \"ठीक है — मैं आपकी बात हमारे support executive से करा रही हूँ। कृपया line पर बने रहिए।\", \"queue\": \"partner_support\"}}, {\"x\": 820, \"y\": 300, \"id\": \"n_end\", \"kind\": \"end\", \"label\": \"Call ends\"}]','[{\"id\": \"e_n_start__n_ask_r_deduction_amount\", \"to\": \"n_ask_r_deduction_amount\", \"from\": \"n_start\"}, {\"id\": \"e_n_ask_r_deduction_amount__n_ask_r_order_last4\", \"to\": \"n_ask_r_order_last4\", \"from\": \"n_ask_r_deduction_amount\"}, {\"id\": \"e_n_ask_r_order_last4__n_ask_r_deduction_date\", \"to\": \"n_ask_r_deduction_date\", \"from\": \"n_ask_r_order_last4\"}, {\"id\": \"e_n_ask_r_deduction_date__n_ask_r_store_handover\", \"to\": \"n_ask_r_store_handover\", \"from\": \"n_ask_r_deduction_date\"}, {\"id\": \"e_n_ask_r_store_handover__n_cond_store_handover\", \"to\": \"n_cond_store_handover\", \"from\": \"n_ask_r_store_handover\"}, {\"id\": \"e_n_cond_store_handover__n_ask_r_store_handover_date__309\", \"to\": \"n_ask_r_store_handover_date\", \"from\": \"n_cond_store_handover\", \"label\": \"true\"}, {\"id\": \"e_n_cond_store_handover__n_api__1995\", \"to\": \"n_api\", \"from\": \"n_cond_store_handover\", \"label\": \"false\"}, {\"id\": \"e_n_ask_r_store_handover_date__n_api\", \"to\": \"n_api\", \"from\": \"n_ask_r_store_handover_date\"}, {\"id\": \"e_n_api__n_confirmed__1990\", \"to\": \"n_confirmed\", \"from\": \"n_api\", \"label\": \"success\"}, {\"id\": \"e_n_api__n_pending__8902\", \"to\": \"n_pending\", \"from\": \"n_api\", \"label\": \"failure\"}, {\"id\": \"e_n_confirmed__n_hub_more\", \"to\": \"n_hub_more\", \"from\": \"n_confirmed\"}, {\"id\": \"e_n_pending__n_hub_more\", \"to\": \"n_hub_more\", \"from\": \"n_pending\"}, {\"id\": \"e_n_hub_more__n_handover__4612\", \"to\": \"n_handover\", \"from\": \"n_hub_more\", \"label\": \"another issue/one more issue/ek aur issue/aur ek issue/doosra issue/dusra issue/aur bhi issue/dusri concern/एक और इशू/और एक इशू/दूसरा इशू/और भी इशू/दूसरी कंसर्न\"}, {\"id\": \"e_n_hub_more__n_handover__6244\", \"to\": \"n_handover\", \"from\": \"n_hub_more\", \"label\": \"agent/human/executive/supervisor/manager/support executive/customer care/insaan se/aadmi se/kisi se baat karao/एजेंट/सुपरवाइज़र/मैनेजर/इंसान से/आदमी से/किसी से बात कराओ\"}, {\"id\": \"e_n_hub_more__n_msg_close__7077\", \"to\": \"n_msg_close\", \"from\": \"n_hub_more\", \"label\": \"no/nothing/nahi/bas/bas itna hi/that\'s all/thats all/thank you/thanks/theek hai bas/nothing else/ho gaya/nahi bas/नहीं/बस/बस इतना ही/धन्यवाद/शुक्रिया/ठीक है बस/हो गया\"}, {\"id\": \"e_n_msg_close__n_end\", \"to\": \"n_end\", \"from\": \"n_msg_close\"}]','[]','2026-08-31 18:46:26','2026-08-31 18:46:27','usr_9b626787e757','usr_9b626787e757',0,NULL,NULL),('wf_f42f4b4f51a4','tn_ae9d817e8fed','bot_d0679769048d','Billing journey',2,'approved','[{\"id\": \"n1\", \"kind\": \"start\", \"label\": \"Call starts\"}, {\"id\": \"n2\", \"kind\": \"api\", \"label\": \"Fetch invoice\", \"config\": {\"connectionId\": \"api_1dbf064d85f1\"}}, {\"id\": \"n3\", \"kind\": \"end\", \"label\": \"End call\"}]','[{\"id\": \"e1\", \"to\": \"n2\", \"from\": \"n1\"}, {\"id\": \"e2\", \"to\": \"n3\", \"from\": \"n2\"}]','[]','2026-08-25 20:49:05','2026-08-25 20:49:05',NULL,NULL,0,NULL,NULL),('wf_f7f176cad21c','tn_22a809aecf66','bot_39db9985b7d5','DPD 60-210 collection call',2,'approved','[{\"x\": 40, \"y\": 40, \"id\": \"n_start\", \"kind\": \"start\", \"label\": \"Outbound call connected\"}, {\"x\": 40, \"y\": 150, \"id\": \"n_push\", \"kind\": \"intent\", \"label\": \"Rung 1: push\", \"config\": {\"prompt\": \"Aap call par rehte hue hi UPI ke through abhi payment complete kar dijiye, taaki hum turant aapki help kar sakein aur payment se related koi dikkat na ho. Saath hi aapka profile bhi turant update ho jayega. Kya aap abhi payment karenge?\"}}, {\"x\": 40, \"y\": 260, \"id\": \"n_history_ask\", \"kind\": \"intent\", \"label\": \"Rung 2: history_ask\", \"config\": {\"prompt\": \"Aapke profile par dikh raha hai ki aapne pehle kai baar loan time se repay kiya hai — aap mPokket ke ek achhe user rahe hain, aur main nahi chahta ki aapka yeh record kharab ho. System records ke hisaab se pehle bhi payment ke baare mein baat hui thi aur promise ke baad bhi payment receive nahi hui, aur aapki last payment ke baad se koi naya payment update nahi hua hai. Kya aap abhi payment complete karenge?\"}}, {\"x\": 40, \"y\": 370, \"id\": \"n_funds\", \"kind\": \"intent\", \"label\": \"Rung 3: funds\", \"config\": {\"prompt\": \"Aap apni savings se, ya kisi friend ya family se arrange karke bhi payment kar sakte hain — isse aapko koi extra penalty nahi deni hogi. Kya aap payment ka intezaam kar sakte hain?\"}}, {\"x\": 40, \"y\": 480, \"id\": \"n_penalty_long\", \"kind\": \"intent\", \"label\": \"Rung 4: penalty_long\", \"config\": {\"prompt\": \"Dekhiye, repayment date par payment na hone se penalty charges din-b-din badhte rehte hain, aur already kaafi extra amount lag chuka hai. Hum nahi chahte ki delay ki wajah se aapko aur extra charges dene paden — woh amount aap kisi aur zaroori kaam mein use kar sakte hain. Isliye request hai ki abhi hi payment complete kar dijiye. Kya aap abhi payment karenge?\"}}, {\"x\": 40, \"y\": 590, \"id\": \"n_cibil_long\", \"kind\": \"intent\", \"label\": \"Rung 5: cibil_long\", \"config\": {\"prompt\": \"Time par repayment na karne se aapke CIBIL par bhi impact ho raha hai, aur aap jaante hain aaj ke time mein CIBIL kitna important hai. Ghar mein kabhi bhi medical ya koi emergency aa sakti hai jismein loan ki zarurat pad sakti hai. Agar CIBIL kharab rahega toh kisi bhi tarah ka loan lene mein dikkat hogi, aur mila bhi toh interest rate kaafi high hoga. EMI par koi saman lene mein bhi pareshani ho sakti hai. Hum nahi chahte ki aapko yeh dikkat ho, isliye request hai ki payment complete kar dijiye. Kya aap payment karenge?\"}}, {\"x\": 40, \"y\": 700, \"id\": \"n_limit_block\", \"kind\": \"intent\", \"label\": \"Rung 6: limit_block\", \"config\": {\"prompt\": \"Agar aap time par payment nahi karte, toh aapka credit limit decrease ho sakta hai aur limit block hone ke bhi chances hain. Lekin sahi date par repayment karne se aapka credit limit gradually ₹50,000 tak increase ho sakta hai. Kya aap abhi payment complete karenge?\"}}, {\"x\": 40, \"y\": 810, \"id\": \"n_notice\", \"kind\": \"intent\", \"label\": \"Rung 7: notice\", \"config\": {\"prompt\": \"Ek important baat — aapki profile par recovery notice ki soft copy active ho chuki hai, jo aapke liye theek nahi hai. Is situation ko avoid karne ke liye jaldi se payment complete kar dijiye. Kya aap abhi payment karenge?\"}}, {\"x\": 40, \"y\": 920, \"id\": \"n_visit\", \"kind\": \"intent\", \"label\": \"Rung 8: visit\", \"config\": {\"prompt\": \"Recovery notice ki hard copy ke saath collection team aapke permanent address par repayment ke regarding discussion ke liye visit kar sakti hai. Chhoti si amount ke liye aisi situation aapke liye comfortable nahi hogi, aur hum bhi nahi chahte ki aisa ho. Isliye request hai ki call par rehte hue abhi payment complete kar dijiye. Kya aap taiyar hain?\"}}, {\"x\": 40, \"y\": 1030, \"id\": \"n_writeoff\", \"kind\": \"intent\", \"label\": \"Rung 9: writeoff\", \"config\": {\"prompt\": \"Aakhri important baat — aapka loan account kaafi lambe samay se overdue hai. Agar payment aur delay hota hai, toh account Write-Off category mein ja sakta hai, jisse aapke CIBIL par serious negative impact padega aur future mein loan milna bahut mushkil ho jayega. Request hai ki turant payment arrange karke apna account regularize kar dein. Kya aap abhi payment karenge?\"}}, {\"x\": 360, \"y\": 150, \"id\": \"n_ptype\", \"kind\": \"ask\", \"label\": \"Full or partial payment\", \"config\": {\"question\": \"Bahut achha! Kya aap apna poora overdue amount pay karenge, ya partial payment karenge?\", \"synonyms\": {\"full\": [\"poora\", \"pura\", \"puri\", \"complete\", \"whole\", \"saara\", \"sara\", \"full\", \"पूरा\", \"पूरी\", \"सारा\", \"पूर्ण\"], \"partial\": [\"partial\", \"part payment\", \"aadha\", \"adha\", \"half\", \"thoda\", \"installment\", \"instalment\", \"kisht\", \"आधा\", \"आधी\", \"थोड़ा\", \"थोड़ी\", \"किस्त\", \"किश्त\"]}, \"variable\": \"payment_type\", \"entityType\": \"list\"}}, {\"x\": 360, \"y\": 260, \"id\": \"n_mop\", \"kind\": \"ask\", \"label\": \"Mode of payment\", \"config\": {\"question\": \"Kaunse madhyam se aapka payment hoga – Debit Card ya UPI?\", \"synonyms\": {\"UPI\": [\"upi\", \"bhim\", \"paytm\", \"gpay\", \"google pay\", \"phonepe\", \"phone pe\", \"qr\", \"यूपीआई\", \"यू पी आई\", \"भीम\", \"पेटीएम\", \"फोनपे\", \"फोन पे\", \"गूगल पे\", \"क्यूआर\"], \"Debit Card\": [\"debit\", \"card\", \"atm\", \"डेबिट\", \"कार्ड\", \"एटीएम\"]}, \"variable\": \"payment_method\", \"entityType\": \"list\"}}, {\"x\": 360, \"y\": 370, \"id\": \"n_guide\", \"kind\": \"message\", \"label\": \"Payment guidance\", \"config\": {\"text\": \"Dhanyavaad! Kripya mPokket app kholkar apna payment abhi complete kar dijiye. Payment complete hote hi aapka profile turant update ho jayega aur koi extra penalty charges nahi lagenge. Main call par kabhi card number, PIN ya OTP nahi maangta — yeh details kisi ke saath share na karein.\"}}, {\"x\": 360, \"y\": 480, \"id\": \"n_close\", \"kind\": \"end\", \"label\": \"Close call\", \"config\": {\"text\": \"mPokket mein samay dene ke liye dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 40, \"y\": 1140, \"id\": \"n_refuse_end\", \"kind\": \"end\", \"label\": \"Refusal close\", \"config\": {\"text\": \"Main aapki baat note kar raha hun, lekin aapko inform karna mera farz hai — account write-off ke kareeb hai, recovery process active hai, aur collection team aapke address par visit kar sakti hai. In sab se bachne ka ek hi tareeka hai — jald se jald payment complete karna. Kripya aaj hi mPokket app se payment kariye. mPokket mein samay dene ke liye dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 660, \"y\": 150, \"id\": \"n_callback\", \"kind\": \"end\", \"label\": \"Callback close\", \"config\": {\"text\": \"Koi baat nahi, hum aapko baad mein call kar lenge. Kripya jitni jaldi ho sake mPokket app se apna payment complete kar dijiye, taaki koi extra charges na lagen. Dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 660, \"y\": 260, \"id\": \"n_wrong\", \"kind\": \"end\", \"label\": \"Wrong person close\", \"config\": {\"text\": \"Maaf kijiye, lagta hai yeh call galat number par lag gayi. Aapka samay lene ke liye khed hai. Dhanyavaad, aapka din shubh ho!\"}}, {\"x\": 660, \"y\": 370, \"id\": \"n_paid\", \"kind\": \"handover\", \"label\": \"Already paid — verify\", \"config\": {\"text\": \"Agar aapne payment already complete kar di hai, toh dhanyavaad! Main aapko hamare agent se connect kar raha hun jo aapki payment verify kar denge. Kripya line par bane rahiye.\"}}, {\"x\": 660, \"y\": 480, \"id\": \"n_agent\", \"kind\": \"handover\", \"label\": \"Agent handover\", \"config\": {\"text\": \"Main aapko hamare ek agent se connect kar raha hun. Kripya line par bane rahiye.\"}}]','[{\"id\": \"e_start\", \"to\": \"n_push\", \"from\": \"n_start\"}, {\"id\": \"e_push_paid\", \"to\": \"n_paid\", \"from\": \"n_push\", \"label\": \"paid,already,kar di,kar diya,kar chuka,kar chuki,ho chuki,ho chuka,ho gaya,ho gayi,kat gaya,kat gayi,कर दी,कर दिया,कर चुका,हो चुकी,हो चुका,हो गया,हो गई,कट गया,कट गई\"}, {\"id\": \"e_push_wrong\", \"to\": \"n_wrong\", \"from\": \"n_push\", \"label\": \"galat number,wrong number,main woh nahi,mai woh nahi,koi aur,is naam,mera loan nahi,loan liya hi nahi,गलत नंबर,मैं वो नहीं,कोई और,इस नाम,मेरा लोन नहीं\"}, {\"id\": \"e_push_cb\", \"to\": \"n_callback\", \"from\": \"n_push\", \"label\": \"busy,meeting,call back,callback,baad mein call,call karna,drive,gaadi,vyast,बाद में कॉल,कॉल करना,व्यस्त,मीटिंग,गाड़ी\"}, {\"id\": \"e_push_agent\", \"to\": \"n_agent\", \"from\": \"n_push\", \"label\": \"agent,customer care,insaan,supervisor,manager,adhikari,एजेंट,कस्टमर केयर,इंसान,सुपरवाइज़र,मैनेजर\"}, {\"id\": \"e_push_refuse\", \"to\": \"n_history_ask\", \"from\": \"n_push\", \"label\": \"nahi,nahin,paise,dikkat,problem,mushkil,baad,kal,parso,salary,agle,pagar,tankhwah,नहीं,नही,पैसे,पैसा,दिक्कत,मुश्किल,बाद,कल,परसों,सैलरी,अगले\"}, {\"id\": \"e_push_agree\", \"to\": \"n_ptype\", \"from\": \"n_push\", \"label\": \"haan,yes,okay,theek,bilkul,zaroor,jarur,taiyar,ready,kar deta,kar dunga,kar doonga,karunga,karungi,upi,debit,card,हाँ,हां,जी,ठीक,बिल्कुल,ज़रूर,जरूर,तैयार,कर देता,कर दूंगा,करूंगा,करूंगी,यूपीआई,डेबिट,कार्ड\"}, {\"id\": \"e_push_else\", \"to\": \"n_history_ask\", \"from\": \"n_push\", \"label\": \"else\"}, {\"id\": \"e_history_ask_paid\", \"to\": \"n_paid\", \"from\": \"n_history_ask\", \"label\": \"paid,already,kar di,kar diya,kar chuka,kar chuki,ho chuki,ho chuka,ho gay